export const jaBlog: BlogTable = {
  "hybrid-vs-grid-tie-vs-off-grid": {
    title: "ハイブリッド vs 系統連系 vs オフグリッド：プロジェクトに合うインバータートポロジーの選び方",
    description: "太陽光プロジェクト向け3つのインバータートポロジーの実践的な比較 — それぞれの役割、コスト、そして市場に合った選び方。",
    tags: [
      "インバーターガイド",
      "太陽光発電の基礎",
    ],
    bodyHtml: "<p>インバーターのトポロジー選定は、あらゆる太陽光プロジェクトにおいて最初にして最も重要な意思決定です。本ガイドでは、主流の3つのトポロジーを比較し、B2Bバイヤーから実際に見られるプロジェクトシナリオに当てはめて整理します。</p>\n<h2>早見比較</h2>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>系統連系</th>\n<th>オフグリッド</th>\n<th>ハイブリッド</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>系統への売電</td>\n<td>あり</td>\n<td>なし</td>\n<td>設定可能</td>\n</tr>\n<tr>\n<td>蓄電池対応</td>\n<td>なし</td>\n<td>あり</td>\n<td>あり</td>\n</tr>\n<tr>\n<td>停電時の動作</td>\n<td>なし</td>\n<td>あり</td>\n<td>あり（&#x3C; 10 ms）</td>\n</tr>\n<tr>\n<td>主な用途</td>\n<td>電気料金の削減</td>\n<td>系統なし</td>\n<td>蓄電池＋バックアップ</td>\n</tr>\n<tr>\n<td>相対コスト</td>\n<td>最低</td>\n<td>中</td>\n<td>最高</td>\n</tr>\n</tbody>\n</table>\n<h2>系統連系：既存の系統でROIを最大化</h2>\n<p>系統連系インバーターは直流を交流に変換し、余剰電力を系統へ売電します。ワットあたりのコストが最も低く、効率も最も高いですが、法規制により停電時は停止する必要があり、バックアップ電源はありません。</p>\n<p><strong>最適な用途：</strong> ネットメータリングや固定価格買取制度がある市場、および純粋に経済性を目的とするお客様。</p>\n<h2>オフグリッド：系統が届かない場所に電力を</h2>\n<p>オフグリッドインバーターは、太陽光発電と蓄電池から独自のミニグリッドを構成し、多くの場合バックアップとして発電機入力を備えます。容量設計の徹底が重要です。平均月ではなく、最も条件の厳しい月をカバーしなければなりません。</p>\n<p><strong>最適な用途：</strong> 農村電化、通信基地局、離島、山小屋。</p>\n<p>当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>は900–5000 Wの蓄電池ベースシステムに対応し、<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>はPV専用サイト向けにMPPT充電コントローラーを内蔵し、最大11 kWまで対応します。</p>\n<h2>ハイブリッド：急成長中の中間領域</h2>\n<p>ハイブリッドインバーターは、系統連系インバーターと蓄電池充電器を組み合わせたものです。採算が合うときに売電し、電気が安いときに充電し、系統停電時には住宅をバックアップします。これらすべてを1台で実現します。</p>\n<p><strong>最適な用途：</strong> 停電頻度が増加している市場、時間帯別料金、自家消費インセンティブのある市場。当社が対応するほとんどの地域で、最も急速に成長しているセグメントです。</p>\n<h2>B2Bバイヤーの意思決定を当社が支援します</h2>\n<p>対象市場と典型的なプロジェクト概要を当社のセールスエンジニアにお知らせください。お客様のカタログに最適なトポロジーの組み合わせと、仕向国に必要な認証要件をご提案します。まずは<a href=\"/contact/\">お問い合わせフォーム</a>からご連絡ください。</p>",
  },
  "how-to-size-a-hybrid-solar-system": {
    title: "ハイブリッド太陽光システムの容量設計：ステップ・バイ・ステップ・ワークシート",
    description: "5つのステップでハイブリッド（太陽光 + 蓄電池）システムを設計する：負荷監査、PVアレイ、蓄電池容量、インバーター定格、コンプライアンス確認 — 計算例つき。",
    tags: [
      "容量設計ガイド",
      "ハイブリッドシステム",
    ],
    bodyHtml: "<p>適切なサイジングは、顧客を満足させるハイブリッドシステムと、失望させるシステムを分けます。以下は、当社のエンジニアが使用している5ステップの手法であり、顧客プロジェクトに直接適用できます。</p>\n<h2>ステップ1：負荷の洗い出し</h2>\n<p>すべての負荷について、消費電力と1日の稼働時間をリストアップします。その結果が、kWh単位の1日あたりのエネルギー収支です。推測しないでください。データロガーや顧客の電気料金明細は、常に推定よりも優れています。</p>\n<p><strong>例：</strong> 12 kWh/日を使用し、夕方のピークが6 kWの家庭。</p>\n<h2>ステップ2：PVアレイのサイジング</h2>\n<p>1日のエネルギー量を現地のピーク日照時間で割り、システム損失、バッテリーのラウンドトリップ効率、パネルの劣化のために15–25%を加算します。</p>\n<p><strong>例：</strong> 12 kWh ÷ 4.5 日照時間 × 1.25 ≈ 3.3 kW → 4 kWアレイ（500 Wパネル×8枚）は余裕を残します。</p>\n<h2>ステップ3：バッテリーバンクのサイジング</h2>\n<p>バックアップ対象を決定します。重要負荷のみ（冷蔵庫、照明、ルーター）か、家全体か。必要な自立運転時間（または日数）を掛け、インバーターの最大充電電流を尊重します。PV出力を吸収するには小さすぎるバッテリーバンクは、発電を無駄にします。</p>\n<p><strong>例：</strong> 8 kWhの蓄電容量（48 V × 約170 Ahの使用可能容量）は、1日の自立運転で重要負荷を一晩カバーします。</p>\n<h2>ステップ4：インバーターの選定</h2>\n<p>インバーターの連続定格は同時ピーク負荷を上回る必要があり、そのサージ定格はモーター始動をカバーする必要があります。5 kW連続 / 10 kWサージのユニットは、<a href=\"/products/\">インバーターカタログ</a>をご覧ください。非同時負荷に分割された6 kWの夕方ピークを、突入電流マージンをもって余裕で処理します。</p>\n<p>計算例のようなシステムの場合、当社の<a href=\"/products/off-grid-solar-inverters/5000w/\">5000 Wオフグリッド太陽光インバーター</a>は、正弦波出力と内蔵MPPT充電コントローラーを組み合わせており、PVアレイ、バッテリーバンク、負荷がすべて1台の壁掛けユニットを共有します。</p>\n<h2>ステップ5：コンプライアンスの確認</h2>\n<p>見積もり前に、対象市場の系統連系規程、逆潮流制限、認証要件を確認してください。ここでOEMサポートがその価値を発揮します。当社は生産ラインで市場固有のファームウェアを事前設定します。</p>\n<h2>レビューが必要ですか？</h2>\n<p>負荷調査と対象市場を<a href=\"/contact/\">お問い合わせフォーム</a>からお送りください。当社のエンジニアがサイジングをレビューし、適切なモデルを無償でご提案します。</p>",
  },
  "12v-24v-48v-inverter-system": {
    title: "12V、24V、48Vインバーター：適切なシステム電圧の選び方",
    description: "12V、24V、48Vのオフグリッドシステムから選ぶ方法 — ケーブルコスト、効率、インバーターの入手性、システム電圧を決定するための実用的なルール。",
    tags: [
      "インバーターガイド",
      "オフグリッド",
      "太陽光の基礎",
    ],
    bodyHtml: "<p>システム電圧 — 12 V、24 V、48 V — はオフグリッド設計の初期段階で決まり、後から変更するのは困難です。これはケーブルサイズと効率を、コンポーネントのコストや入手性と天秤にかけることになります。</p>\n<h2>基本的なトレードオフ</h2>\n<p>電力は電圧 × 電流です。電力が一定の場合、<strong>電圧が高いほど電流は小さくなり</strong>、電流が小さいほどケーブルは細く安価になり、損失も減ります。</p>\n<table>\n<thead>\n<tr>\n<th>システム</th>\n<th>一般的なバッテリー</th>\n<th>インバーター範囲</th>\n<th>同一電力時のケーブルサイズ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>12 V</td>\n<td>単一バッテリー</td>\n<td>300–1,500 W</td>\n<td>太く、高価</td>\n</tr>\n<tr>\n<td>24 V</td>\n<td>2台のバッテリー</td>\n<td>1–3 kW</td>\n<td>中程度</td>\n</tr>\n<tr>\n<td>48 V</td>\n<td>4台のバッテリー（またはLiFePO4パック）</td>\n<td>1–11 kW</td>\n<td>細く、安価</td>\n</tr>\n</tbody>\n</table>\n<h2>実用的な目安</h2>\n<ul>\n<li><strong>12 V</strong> — 約1 kW未満の小規模負荷：キャビン、キャンプ、小型ボート、ポータブル設備。コンポーネントの入手性は広範ですが、ケーブルは太くする必要があります。</li>\n<li><strong>24 V</strong> — 1～3 kWの中規模負荷：小さな住宅、ワークショップ、RV。コンパクトなシステムに適した中間的な選択肢です。</li>\n<li><strong>48 V</strong> — 約3 kWを超えるものすべて：一般住宅、通信、農場、ビジネス。ケーブルコストを抑えられ、より高出力のインバーターも豊富にあります。</li>\n</ul>\n<h2>大規模システムで48 Vが優れている理由</h2>\n<p>およそ3 kWを超えると、12 Vバンクは非常に太いケーブル（5 kWシステムではしばしば2× 000 AWG）が必要になり、ライン損失でかなりのエネルギーを無駄にします。48 Vなら電流を低く抑えられます — 48 Vで5 kWのインバーターは約104 Aを消費しますが、これは通常サイズのケーブルで余裕を持って対応できます。</p>\n<h2>インバーターの選定</h2>\n<p>まず<strong>インバーターを選び</strong>、そのDC入力電圧に合わせてバンクを構築します — 逆ではありません。このサイトのすべての製品ページには、仕様表にDC入力範囲が記載されているため、バッテリーを見積もる前にシステム電圧を確認できます。</p>\n<p>当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>は12 V、24 V、48 Vに対応し（一部モデルは60 V、72 Vにも対応）、<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>は同じ電圧範囲に内蔵MPPTコントローラーを追加します。</p>\n<section aria-label=\"システム電圧 — よくある質問\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">システム電圧 — よくある質問</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">システム電圧は後から変更できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">簡単にはできません — インバーター、バッテリー、コントローラー、配線はすべて電圧に従います。設計時に決定し、そのまま維持してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">48Vは12Vより効率的ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">同じ電力であれば、はい。電流が低いほどケーブル内のI²R損失が減るためです。効率の差はシステム規模が大きくなるほど広がります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">12Vのコンポーネントは安価ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">一部は安価です、特に小型アクセサリー。しかし大規模システムでは、余分なケーブルコストと損失が節約分をすぐに上回ります。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"システム電圧は後から変更できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"簡単にはできません — インバーター、バッテリー、コントローラー、配線はすべて電圧に従います。設計時に決定し、そのまま維持してください。\"}},{\"@type\":\"Question\",\"name\":\"48Vは12Vより効率的ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"同じ電力であれば、はい。電流が低いほどケーブル内のI²R損失が減るためです。効率の差はシステム規模が大きくなるほど広がります。\"}},{\"@type\":\"Question\",\"name\":\"12Vのコンポーネントは安価ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"一部は安価です、特に小型アクセサリー。しかし大規模システムでは、余分なケーブルコストと損失が節約分をすぐに上回ります。\"}}]}</script>",
  },
  "how-many-solar-panels-for-off-grid": {
    title: "オフグリッドシステムに必要な太陽光パネルの枚数は？",
    description: "オフグリッドインバーターシステムのPVアレイを選定するための実用的なワークシート — 日負荷、日照時間、ディレーティング、そして当社のエンジニアが使用する数値を用いた計算例。",
    tags: [
      "選定ガイド",
      "オフグリッド",
    ],
    bodyHtml: "<p>オフグリッドプロジェクトで最もよく見られる選定ミスは、太陽光アレイの容量不足です。パネルはバッテリーやインバーターよりも後から交換するのが安価であるため、この数値を正確に求めることが設計の中でも特に重要です。</p>\n<h2>ステップ1：1日の必要電力量（Wh/日）を求める</h2>\n<p>すべての負荷、その消費電力（ワット）、および1日あたりの使用時間をリストアップします。\n掛けて足し合わせます：ワット × 時間 = 1日あたりのワット時。</p>\n<p><strong>計算例：</strong></p>\n<table>\n<thead>\n<tr>\n<th>負荷</th>\n<th>ワット</th>\n<th>時間/日</th>\n<th>Wh/日</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>照明</td>\n<td>40</td>\n<td>5</td>\n<td>200</td>\n</tr>\n<tr>\n<td>冷蔵庫</td>\n<td>150</td>\n<td>8</td>\n<td>1,200</td>\n</tr>\n<tr>\n<td>テレビ</td>\n<td>100</td>\n<td>4</td>\n<td>400</td>\n</tr>\n<tr>\n<td>携帯電話の充電器</td>\n<td>15</td>\n<td>4</td>\n<td>60</td>\n</tr>\n<tr>\n<td>ウォーターポンプ</td>\n<td>300</td>\n<td>1</td>\n<td>300</td>\n</tr>\n<tr>\n<td><strong>合計</strong></td>\n<td></td>\n<td></td>\n<td><strong>2,160 Wh/日</strong></td>\n</tr>\n</tbody>\n</table>\n<h2>ステップ2：システム損失を調整する</h2>\n<p>オフグリッドシステムでは、変換、配線、バッテリー充電でエネルギーが失われます。\n保守的な設計では、負荷に <strong>1.3</strong>（30%のディレーティング）を掛けて、アレイが実際に供給する必要のあるエネルギーを求めます：</p>\n<p><strong>2,160 Wh × 1.3 = 2,808 Wh/日がPVから必要</strong></p>\n<h2>ステップ3：日照時間を推定する</h2>\n<p>「ピーク日照時間」とは、その地点での最大強度の太陽光に相当する1日あたりの時間です。これは日照時間（daylight hours）とは<strong>異なります</strong>。一般的な値：</p>\n<ul>\n<li>北ヨーロッパ：2.5～3.5</li>\n<li>中央ヨーロッパ：3.5～4.5</li>\n<li>地中海：4.5～5.5</li>\n<li>中東/北アフリカ：5.5～6.5</li>\n<li>東南アジア/赤道地域：4.5～5.5</li>\n<li>米国南西部：5.5～6.5</li>\n</ul>\n<p>発電機のバックアップがない限り、年間平均ではなく、最も悪い月の保守的な数値を使用してください。</p>\n<h2>ステップ4：アレイサイズを計算する</h2>\n<p><strong>アレイワット数 = 1日のPVエネルギー ÷ 日照時間 ÷ ディレーティング</strong></p>\n<p>2,808 Whが必要で、例えば4.5日照時間の場合：</p>\n<p><strong>2,808 ÷ 4.5 = 624 Wが最小アレイサイズ</strong></p>\n<p>曇りの連続やパネルの劣化に備えて、さらに10～20%のマージンを追加することをお勧めします。この例では、約<strong>700～750 W</strong>のパネルとなります。</p>\n<h2>ステップ5：アレイをインバーター/コントローラーに適合させる</h2>\n<ul>\n<li>オフグリッド太陽光インバーターの<strong>MPPT動作電圧範囲</strong>を確認し、ストリング電圧がその範囲の中央に収まるように設計します。</li>\n<li>アレイ電力をコントローラーの最大PV入力定格内に抑えます。</li>\n<li>ストリング電流をコントローラーの定格入力電流以下に配線します。</li>\n</ul>\n<p>当社の<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>には、MPPT充電コントローラーが内蔵されています。各製品ページの仕様表からPV入力範囲を直接確認できるため、上記のアレイ計算は、見積もり中の実際のモデルにそのまま当てはめることができます。</p>\n<h2>クイックリファレンス：インバーターあたりのパネル枚数</h2>\n<p>これらの数値は、約550 Wのパネル、4.5日照時間、1.3のディレーティングを前提としています：</p>\n<table>\n<thead>\n<tr>\n<th>インバーターサイズ</th>\n<th>典型的なアレイ (W)</th>\n<th>パネル枚数 (約550 W)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1.5～2 kW</td>\n<td>900～1,200</td>\n<td>2</td>\n</tr>\n<tr>\n<td>3 kW</td>\n<td>1,500～1,800</td>\n<td>3</td>\n</tr>\n<tr>\n<td>5 kW</td>\n<td>2,400～3,000</td>\n<td>5</td>\n</tr>\n<tr>\n<td>8 kW</td>\n<td>3,600～4,500</td>\n<td>7～8</td>\n</tr>\n</tbody>\n</table>\n<section aria-label=\"太陽光アレイの選定 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">太陽光アレイの選定 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">アレイが容量不足だとどうなりますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">曇りの日にはバッテリーが完全に充電されず、系統連系や発電機のバックアップに頼る頻度が高くなります。オフグリッドシステムでは、早すぎる低電圧カットオフとして現れます。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">アレイを安全に過大にすることはできますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">はい、インバーターのMPPT入力制限内であれば可能です。過大にすると冬季の発電量が向上し、バッテリーを満充電に保つことができます。コントローラーが余剰電力を抑制します。定格PV入力電圧と電流の範囲内に収めてください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">パネルはインバーターのワット数と1対1で一致させる必要がありますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。アレイは1日のエネルギーに合わせて選定され、インバーターはピーク負荷に合わせて選定されます。当社の選定例では、3 kWインバーターはしばしば1.5～1.8 kWのアレイで運転されます。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"アレイが容量不足だとどうなりますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"曇りの日にはバッテリーが完全に充電されず、系統連系や発電機のバックアップに頼る頻度が高くなります。オフグリッドシステムでは、早すぎる低電圧カットオフとして現れます。\"}},{\"@type\":\"Question\",\"name\":\"アレイを安全に過大にすることはできますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"はい、インバーターのMPPT入力制限内であれば可能です。過大にすると冬季の発電量が向上し、バッテリーを満充電に保つことができます。コントローラーが余剰電力を抑制します。定格PV入力電圧と電流の範囲内に収めてください。\"}},{\"@type\":\"Question\",\"name\":\"パネルはインバーターのワット数と1対1で一致させる必要がありますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。アレイは1日のエネルギーに合わせて選定され、インバーターはピーク負荷に合わせて選定されます。当社の選定例では、3 kWインバーターはしばしば1.5～1.8 kWのアレイで運転されます。\"}}]}</script>",
  },
  "low-frequency-vs-high-frequency-inverter": {
    title: "低周波インバーターと高周波インバーター：プロジェクトに最適なのはどちら？",
    description: "低周波インバーターと高周波インバーターを比較し、サージ能力、重量、コスト、信頼性、そしてさまざまなオフグリッド用途に適した選択肢を解説します。",
    tags: [
      "インバーターガイド",
      "オフグリッド",
      "太陽光の基礎",
    ],
    bodyHtml: "<p>低周波と高周波は、インバーターがDCをACに変換する方式を表し、その違いがサージ処理、重量、長期的な信頼性を左右します。どちらもオフグリッド用に販売されていますが、適切な選択は負荷によって決まります。</p>\n<h2>両者の違い</h2>\n<p><strong>低周波インバーター</strong>は、商用周波数で動作する重量のある銅巻線トランスを使用します。トランスが自然なサージ能力と電気的絶縁を提供し、シンプルで実績のあるトポロジーを採用しています。</p>\n<p><strong>高周波インバーター</strong>は、フェライトトランスを用いた高周波スイッチングを使用します。より軽く、小さく、部分負荷時に効率が高いことが多いですが、サージ能力は物理的なトランスではなく電子回路に依存します。</p>\n<h2>比較</h2>\n<table>\n<thead>\n<tr>\n<th>項目</th>\n<th>低周波</th>\n<th>高周波</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>サージ能力</td>\n<td>優れている（短時間で定格の5～8倍）</td>\n<td>中程度（2～3倍）</td>\n</tr>\n<tr>\n<td>重量</td>\n<td>重い（トランス）</td>\n<td>軽い</td>\n</tr>\n<tr>\n<td>コスト</td>\n<td>高い</td>\n<td>低い</td>\n</tr>\n<tr>\n<td>効率</td>\n<td>軽負荷時はやや低い</td>\n<td>多くの場合高い</td>\n</tr>\n<tr>\n<td>待機電力</td>\n<td>高い</td>\n<td>低い</td>\n</tr>\n<tr>\n<td>主な用途</td>\n<td>ポンプ、工具、大型モーター</td>\n<td>家庭用バックアップ、電子機器</td>\n</tr>\n</tbody>\n</table>\n<h2>サージが重要となる場合</h2>\n<p>誘導モーター — 水道ポンプ、コンプレッサー、電動工具 — は、起動時に大きな突入電流を引き込み、多くの場合、運転ワット数の3～7倍に達します。低周波インバーターのトランスはこのサージをより穏やかに吸収するため、ポンプや作業場設備では低周波設計が好まれます。</p>\n<p>照明、コンピューター、家電に電力を供給する一般的な家庭用バックアップでは、高周波インバーターの方が軽く、安価で、効率も高く、通常そのサージ定格で十分です。</p>\n<h2>当社のサポート</h2>\n<p>当社の<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>と<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>は、両方のトポロジーを網羅しています。営業エンジニアに典型的な負荷 — 特にポンプやモーターの用途 — をお知らせください。お客様の市場に適したシリーズをご案内します。</p>\n<section aria-label=\"トポロジー — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">トポロジー — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">低周波インバーターは常に優れていますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。サージ処理には優れていますが、より重く、高価で、軽負荷時には効率が低くなります。電子機器の多い家庭用途では、高周波インバーターの方が多くの場合、費用対効果に優れています。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">水道ポンプにはどの程度のサージ能力が必要ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">ポンプの運転ワット数の少なくとも3倍の定格を持つインバーターを目指し、できれば低周波シリーズを選びましょう。ポンプのデータシートで実際の拘束電流（ロックドロータ電流）を確認してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">高周波インバーターは信頼性が低いですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">本質的にはそうではありません。信頼性は部品の品質、熱設計、試験によって決まります。試験が文書化されており、確かな保証があるメーカーを選びましょう。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"低周波インバーターは常に優れていますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。サージ処理には優れていますが、より重く、高価で、軽負荷時には効率が低くなります。電子機器の多い家庭用途では、高周波インバーターの方が多くの場合、費用対効果に優れています。\"}},{\"@type\":\"Question\",\"name\":\"水道ポンプにはどの程度のサージ能力が必要ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"ポンプの運転ワット数の少なくとも3倍の定格を持つインバーターを目指し、できれば低周波シリーズを選びましょう。ポンプのデータシートで実際の拘束電流（ロックドロータ電流）を確認してください。\"}},{\"@type\":\"Question\",\"name\":\"高周波インバーターは信頼性が低いですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"本質的にはそうではありません。信頼性は部品の品質、熱設計、試験によって決まります。試験が文書化されており、確かな保証があるメーカーを選びましょう。\"}}]}</script>",
  },
  "off-grid-battery-bank-sizing": {
    title: "オフグリッドバッテリーバンクの容量設計：ステップバイステップガイド",
    description: "オフグリッドインバーターシステムのバッテリーバンクの容量設計方法 — 日次容量、放電深度、自律日数、一般的な住宅での計算例",
    tags: [
      "容量設計ガイド",
      "オフグリッド",
      "バッテリー",
    ],
    bodyHtml: "<p>バッテリーバンクはオフグリッドシステムで最も高価な部分であり、最も間違えやすい部分でもあります。容量を小さくしすぎると、曇りの日に早々にシステムが停止します。逆に大きくしすぎると、めったに使わない容量にお金を払うことになります。</p>\n<h2>容量設計の計算式</h2>\n<p><strong>バッテリー容量 (Ah) = 日次エネルギー (Wh) ÷ バッテリー電圧 (V) ÷ 放電深度 (%)</strong></p>\n<p>結果を左右する3つの変数：</p>\n<ol>\n<li><strong>日次エネルギー使用量 (Wh/日)</strong> — 負荷調査から（<a href=\"/blog/how-many-solar-panels-for-off-grid/\">太陽光パネル容量設計ガイド</a>を参照）</li>\n<li><strong>バッテリー電圧 (V)</strong> — 12 V、24 V、または 48 V、インバーターに適合</li>\n<li><strong>放電深度 (DoD)</strong> — バッテリーの使用可能な部分</li>\n</ol>\n<h2>放電深度が重要</h2>\n<p>化学組成によって許容される放電深度が異なります：</p>\n<table>\n<thead>\n<tr>\n<th>バッテリーの種類</th>\n<th>安全な放電深度</th>\n<th>備考</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>鉛蓄電池（液式）</td>\n<td>50%</td>\n<td>定期的な補充電が必要</td>\n</tr>\n<tr>\n<td>鉛蓄電池（AGM / ジェル）</td>\n<td>50–60%</td>\n<td>メンテナンスフリー、中程度のコスト</td>\n</tr>\n<tr>\n<td>LiFePO4</td>\n<td>80–90%</td>\n<td>長寿命、初期コスト高</td>\n</tr>\n</tbody>\n</table>\n<h2>計算例</h2>\n<p>先ほどの<a href=\"/blog/how-many-solar-panels-for-off-grid/\">容量設計ガイド</a>の住宅を続けます：</p>\n<ul>\n<li>日次負荷: <strong>2,160 Wh</strong></li>\n<li>インバーター / システム電圧: <strong>48 V</strong></li>\n<li>バッテリーの種類: <strong>LiFePO4</strong>、放電深度85%</li>\n<li>希望する自律日数（太陽光なしの場合）: <strong>2日</strong></li>\n</ul>\n<p><strong>ステップ1 — バッテリーが蓄えるべき1日あたりのエネルギー：</strong>\n2,160 Wh ÷ 0.85 = <strong>2,541 Wh の使用可能容量</strong></p>\n<p><strong>ステップ2 — 2日間の自律日数を考慮：</strong>\n2,541 × 2 = <strong>5,082 Wh</strong></p>\n<p><strong>ステップ3 — 48 V でのアンペア時容量：</strong>\n5,082 Wh ÷ 48 V = <strong>106 Ah</strong></p>\n<p>実用的な選択：<strong>48 V、100 Ah (≈ 5 kWh)</strong> の LiFePO4 バンク、または余裕を持たせたい場合は 100 Ah のパックを2つ並列接続します。</p>\n<h2>インバーターとの整合</h2>\n<ul>\n<li><strong>DC 入力電圧</strong>がバンクに一致するインバーターを選びます (12/24/48 V)。</li>\n<li>バンクの充電電流を MPPT コントローラーの定格内に保ちます — 5 kWh のバンクは通常 40–60 A で問題なく充電されます。</li>\n<li>LiFePO4 バンクは、インバーターが対応している場合は通信機能 (CAN/RS485) 付きの BMS が必要です。そうすることで充電が正しく停止します。</li>\n</ul>\n<p>当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>は 12 V、24 V、48 V バンクに対応しています（一部モデルは 60 V および 72 V にも対応）— 各製品ページの仕様表に DC 入力範囲が記載されています。</p>\n<section aria-label=\"バッテリー容量設計 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">バッテリー容量設計 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">自律日数は何日を設計すればよいですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">発電機バックアップのある住宅では2～3日が一般的です。バックアップがない遠隔地では3～5日です。自律日数を増やすとバッテリーとコストが増えます。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">1つのバンクに異なる種類のバッテリーを混在させられますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。化学組成や年式が異なると、アンバランス、不均一な充電、早期故障の原因になります。バンク全体を交換するか、同一のパックで拡張してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">大きなインバーターには大きなバッテリーが必要ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">直接は関係ありません。インバーターのサイズはピーク負荷に、バッテリーのサイズは日次エネルギーと自律日数に基づきます。両方を同じシステム電圧に合わせて連携させてください。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"自律日数は何日を設計すればよいですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"発電機バックアップのある住宅では2～3日が一般的です。バックアップがない遠隔地では3～5日です。自律日数を増やすとバッテリーとコストが増えます。\"}},{\"@type\":\"Question\",\"name\":\"1つのバンクに異なる種類のバッテリーを混在させられますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。化学組成や年式が異なると、アンバランス、不均一な充電、早期故障の原因になります。バンク全体を交換するか、同一のパックで拡張してください。\"}},{\"@type\":\"Question\",\"name\":\"大きなインバーターには大きなバッテリーが必要ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"直接は関係ありません。インバーターのサイズはピーク負荷に、バッテリーのサイズは日次エネルギーと自律日数に基づきます。両方を同じシステム電圧に合わせて連携させてください。\"}}]}</script>",
  },
  "off-grid-inverter-installation-guide": {
    title: "オフグリッドインバーター設置ガイド：配線、安全、試運転",
    description: "オフグリッドインバーターの実践的な設置手順 — 配線順序、ブレーカーサイズ、接地、バッテリー接続、初回電源投入前の試運転チェック。",
    tags: [
      "設置ガイド",
      "オフグリッド",
    ],
    bodyHtml: "<p>クリーンで安全な設置は、長年にわたる信頼性の高いオフグリッド電力と、繰り返しのサービスコールとの分かれ目です。このガイドは、当社のエンジニアがシステムを試運転する際に使用する順序に従っています。</p>\n<blockquote>\n<p><strong>安全第一：</strong> このガイドは資格を持つ設置者向けです。バッテリーバンクは非常に高い電流を供給する可能性があります — 端子での短絡は危険です。正しい順序で電源を切断し、絶縁工具を使用してください。</p>\n</blockquote>\n<h2>予期せぬ事態を避ける配線順序</h2>\n<p>この順序で接続し、取り外し時は逆順にします：</p>\n<ol>\n<li><strong>最初に接地</strong> — 電源配線の前に、システム接地（インバーターシャーシ、パネル、およびマニュアルで指定されている場合はバッテリーマイナス）を接続します。</li>\n<li><strong>バッテリーからインバーターへ</strong> — 極性に注意しながら、正しいヒューズまたはブレーカーをラインに入れてバッテリーバンクを接続します。ほとんどのインバーターはDC入力が存在するまで起動しません。</li>\n<li><strong>PVアレイから充電コントローラーへ</strong> — パネルを覆うかブレーカーを開放した状態で、アレイをMPPT入力に配線します。</li>\n<li><strong>AC出力</strong> — 負荷側を最後に接続し、試運転までオフのままにします。</li>\n</ol>\n<h2>ブレーカーとケーブルのサイズ選定</h2>\n<ul>\n<li><strong>DCバッテリーケーブル</strong> — インバーターの最大電流にマージンを加えて選定します。細すぎるケーブルは電圧降下と発熱の最も一般的な原因です。</li>\n<li><strong>バッテリーヒューズ/ブレーカー</strong> — 連続電流を上回る定格とし、バッテリー端子に設置します。</li>\n<li><strong>PVブレーカー</strong> — ストリング電流に適合する定格で、正しいDC定格のものを使用します。</li>\n<li><strong>ACブレーカー</strong> — インバーターの出力定格と現地の法規に適合させます。</li>\n</ul>\n<h2>試運転チェックリスト</h2>\n<p>電源を入れる前に：</p>\n<ul class=\"contains-task-list\">\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> バッテリーとPV接続の極性を確認済み</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> マニュアルに従い、すべての電源端子をトルク管理</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 接地の導通を確認済み</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> バッテリー電圧がインバーターの入力範囲内</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 端子付近に露出した導体がない</li>\n</ul>\n<p>その後、配線と同じ順序で電源を入れます：バッテリー、次にPV、次に負荷。\n最初の数分間はディスプレイを監視してください — この段階でエラーコードや異常な電圧値を確認することが、後の重大な問題を防ぎます。</p>\n<h2>ドキュメントの重要性</h2>\n<p>各設置について、配線図、設定、ファームウェアバージョンを記録します。\nこれにより保証と将来の拡張が容易になります — そして、顧客が販売店の設置チームに期待するプロフェッショナル基準です。</p>\n<section aria-label=\"設置 — よくある質問\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">設置 — よくある質問</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">バッテリーを逆接続してもよいですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">絶対にしないでください — DC入力の逆極性はインバーターの入力段を損傷し、保証が無効になります。接続前に極性を再確認し、ヒューズ付き接続を使用してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">バッテリーとインバーターの間にはどのサイズのケーブルが必要ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">インバーターの最大DC電流に対して少なくとも25%のマージンで選定し、配線長は短くしてください。正確な推奨値についてはマニュアルのケーブル表を参照してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">オフグリッドインバーターには接地接続が必要ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">はい。シャーシとシステム接地は、マニュアルおよび現地の法規に従って接続する必要があります。接地の欠落は安全上の危険であり、奇妙な故障コードの一般的な原因です。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"バッテリーを逆接続してもよいですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"絶対にしないでください — DC入力の逆極性はインバーターの入力段を損傷し、保証が無効になります。接続前に極性を再確認し、ヒューズ付き接続を使用してください。\"}},{\"@type\":\"Question\",\"name\":\"バッテリーとインバーターの間にはどのサイズのケーブルが必要ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"インバーターの最大DC電流に対して少なくとも25%のマージンで選定し、配線長は短くしてください。正確な推奨値についてはマニュアルのケーブル表を参照してください。\"}},{\"@type\":\"Question\",\"name\":\"オフグリッドインバーターには接地接続が必要ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"はい。シャーシとシステム接地は、マニュアルおよび現地の法規に従って接続する必要があります。接地の欠落は安全上の危険であり、奇妙な故障コードの一般的な原因です。\"}}]}</script>",
  },
  "oem-vs-odm-solar-inverter": {
    title: "OEM vs ODM 太陽光インバーター：あなたのビジネスに適した調達モデルはどれか？",
    description: "太陽光インバーター購入者のためのOEMとODMの解説 — それぞれの意味、どちらを選ぶべきか、そしてプライベートブランド、ファームウェア、パッケージのカスタマイズ方法について。",
    tags: [
      "調達ガイド",
      "OEM / ODM",
      "B2B",
    ],
    bodyHtml: "<p>インバーターを調達する販売代理店、設置業者チェーン、ブランドオーナーの方であれば、「OEM」と「ODM」という2つの用語を耳にされるでしょう。これらは異なるカスタマイズのレベルを表しており、適切なモデルを選ぶことは、コスト、スピード、製品に対する制御性に影響します。</p>\n<h2>2つのモデル</h2>\n<p><strong>OEM（Original Equipment Manufacturer）</strong> — 既存の実績ある設計を採用し、自社ブランドで販売します。カスタマイズは主に見た目の部分です：ロゴ、パッケージ、ラベル、マニュアル。ハードウェアとファームウェアはメーカーの標準製品です。</p>\n<p><strong>ODM（Original Design Manufacturer）</strong> — メーカーがお客様の仕様に合わせて設計を開発または変更します：カスタム出力構成、ファームウェアパラメータ、通信プロトコル、さらには筐体のデザインまで。開発期間が長くなる代わりに、真にあなたの製品を手に入れることができます。</p>\n<h2>選択肢の比較</h2>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>OEM</th>\n<th>ODM</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>市場投入までの時間</td>\n<td>速い</td>\n<td>遅い（開発＋検証）</td>\n</tr>\n<tr>\n<td>初期費用</td>\n<td>低い</td>\n<td>高い</td>\n</tr>\n<tr>\n<td>ブランド管理</td>\n<td>ロゴ＋パッケージ</td>\n<td>完全な製品アイデンティティ</td>\n</tr>\n<tr>\n<td>技術的差別化</td>\n<td>ほとんどない</td>\n<td>大きい</td>\n</tr>\n<tr>\n<td>MOQ</td>\n<td>低い</td>\n<td>高い</td>\n</tr>\n<tr>\n<td>最適な用途</td>\n<td>迅速なプライベートブランド展開</td>\n<td>独自の製品ラインの構築</td>\n</tr>\n</tbody>\n</table>\n<h2>実際にカスタマイズ可能な項目</h2>\n<ul>\n<li><strong>プライベートブランド</strong> — ロゴ、ブランドカラー、カートン、マニュアル、表示言語</li>\n<li><strong>ファームウェア</strong> — デフォルトパラメータ、通信プロトコル（CAN/RS485）、お客様の地域向けの系統連系設定</li>\n<li><strong>仕様</strong> — 出力電圧（110/220 V）、DC入力範囲、ソケットタイプ、場合によってはプラットフォームの限界内での電力定格</li>\n<li><strong>品質とコンプライアンス</strong> — 対象市場向けの認証セット</li>\n</ul>\n<h2>適切なパートナーの選び方</h2>\n<p>どのモデルを選ぶにしても、ラベルよりもメーカーの工場が重要です：</p>\n<ul>\n<li>工場は<strong>実在し、検査可能</strong>ですか？ビデオ監査はできますか？</li>\n<li><strong>テストは文書化</strong>されていますか — 機能テスト、エージングテスト、トレーサビリティ？</li>\n<li><strong>注文後のサポート</strong>は利用可能ですか — スペアパーツ、ファームウェア更新、RMA？</li>\n</ul>\n<p>当社は自社工場からOEMとODMの両プログラムをサポートしています — 能力、サービス、プロセスについては<a href=\"/oem-odm/\">OEM / ODMページ</a>をご覧いただくか、対象市場と数量を添えて営業チームまでお問い合わせください。</p>\n<section aria-label=\"調達 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">調達 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">最小発注数量（MOQ）はいくつですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">MOQはモデルとカスタマイズの深さによって異なります。通常、OEMブランディングはフルODM開発よりもMOQが低くなります。計画をお知らせいただければ、現実的なMOQと価格を確認いたします。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">OEMで開始し、後からODMに移行できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">はい。多くのお客様は標準モデルでOEMブランディングを開始し、数量が開発を正当化するようになったら、ファームウェアと仕様のカスタマイズに移行します。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">ODMプロジェクトにおける設計の所有権は誰にありますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">通常、メーカーがコアプラットフォームを所有し、お客様のカスタム構成とブランディングはお客様に帰属します。契約条件はプロジェクトごとにこれを明示的に定めます。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"最小発注数量（MOQ）はいくつですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"MOQはモデルとカスタマイズの深さによって異なります。通常、OEMブランディングはフルODM開発よりもMOQが低くなります。計画をお知らせいただければ、現実的なMOQと価格を確認いたします。\"}},{\"@type\":\"Question\",\"name\":\"OEMで開始し、後からODMに移行できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"はい。多くのお客様は標準モデルでOEMブランディングを開始し、数量が開発を正当化するようになったら、ファームウェアと仕様のカスタマイズに移行します。\"}},{\"@type\":\"Question\",\"name\":\"ODMプロジェクトにおける設計の所有権は誰にありますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"通常、メーカーがコアプラットフォームを所有し、お客様のカスタム構成とブランディングはお客様に帰属します。契約条件はプロジェクトごとにこれを明示的に定めます。\"}}]}</script>",
  },
  "off-grid-solar-system-cost": {
    title: "2026年のオフグリッド太陽光システムの費用はいくらですか？",
    description: "オフグリッド太陽光システムのコストの現実的な内訳 — パネル、インバーター、バッテリー、配線、設置 — 小規模システムと全戸建てシステムの一般的な予算を含みます。",
    tags: [
      "コストガイド",
      "オフグリッド",
      "太陽光基礎",
    ],
    bodyHtml: "<p>オフグリッド太陽光の価格は地域によって大きく異なり、価格は急速に変動するため、このガイドでは固定価格リストではなく、コスト構造と総額を左右する意思決定に焦点を当てます。常にあなたの市場の最新の見積もりを取得してください。</p>\n<h2>コストの内訳</h2>\n<table>\n<thead>\n<tr>\n<th>構成要素</th>\n<th>総額に占める割合</th>\n<th>注記</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>バッテリーバンク</td>\n<td>35–50%</td>\n<td>最大の単一コスト — 化学組成と容量が左右する</td>\n</tr>\n<tr>\n<td>太陽光パネル</td>\n<td>20–30%</td>\n<td>ワットあたりのコストは着実に下落している</td>\n</tr>\n<tr>\n<td>インバーター</td>\n<td>15–25%</td>\n<td>純正弦波とサージ能力が重要</td>\n</tr>\n<tr>\n<td>配線、ブレーカー、架台</td>\n<td>10–15%</td>\n<td>しばしば過小評価される</td>\n</tr>\n<tr>\n<td>設置と設計</td>\n<td>変動する</td>\n<td>人件費は地域によって大きく異なる</td>\n</tr>\n</tbody>\n</table>\n<h2>一般的なシステム予算</h2>\n<p>これらは設置前のハードウェアのみの目安となる範囲です：</p>\n<table>\n<thead>\n<tr>\n<th>システム</th>\n<th>1日あたりのエネルギー</th>\n<th>ハードウェア予算の目安</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>小型キャビン / バックアップ</td>\n<td>1–2 kWh/day</td>\n<td>$1,500–3,000</td>\n</tr>\n<tr>\n<td>家庭、部分負荷</td>\n<td>3–5 kWh/day</td>\n<td>$4,000–8,000</td>\n</tr>\n<tr>\n<td>完全オフグリッド住宅</td>\n<td>8–12 kWh/day</td>\n<td>$10,000–20,000</td>\n</tr>\n<tr>\n<td>農場 / 事業所</td>\n<td>15+ kWh/day</td>\n<td>$20,000+</td>\n</tr>\n</tbody>\n</table>\n<h2>最も重要な決定事項</h2>\n<ol>\n<li><strong>バッテリー化学</strong> — LiFePO4は初期費用が高いですが、サイクル寿命は鉛蓄電池より2～3倍長持ちします。10年の寿命で見ると、LiFePO4の方がしばしば安価です。</li>\n<li><strong>アレイの過剰サイズ化</strong> — パネルを20%多く追加することは、曇天の季節でもバッテリーを満充電に保つ安価な保険です。</li>\n<li><strong>インバーターの品質</strong> — 真のサージ能力と認証試験を備えた純正弦波ユニットは、投資全体を保護します。</li>\n</ol>\n<h2>OEM / ODM が状況を変える場面</h2>\n<p>再販目的で購入する販売店や施工業者にとって、インバーターコストは直接的な調達項目です。<a href=\"/oem-odm/\">OEM / ODM サポート</a> による工場直送供給は、販売店マージンを排除し、あなたの市場向けに出力構成を指定できます — だからこそ、当社が供給するほとんどの施工業者は、小売チャネルではなく当社カタログから始めています。</p>\n<section aria-label=\"コスト — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">コスト — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">なぜバッテリーがコストのそんなに大きな割合を占めるのですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">それはシステムを独立させるエネルギーを貯蔵するからです。化学組成と容量が部品表の大部分を占めるため、容量設計の規律が重要になります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">小さく始めて後で拡張できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">はい。将来の負荷に合わせたサイズのインバーターから始め、時間をかけてアレイとバッテリーバンクを拡張してください。当社のインバーターのほとんどは、シリーズ内での並列拡張をサポートしています。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">自分の市場の正確な価格を知るにはどうすればよいですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">負荷リストと日照時間を当社の営業チームに共有してください — お問い合わせフォームを通じて、あなたの地域向けの最新の工場価格と構成オプションを提供します。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"なぜバッテリーがコストのそんなに大きな割合を占めるのですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"それはシステムを独立させるエネルギーを貯蔵するからです。化学組成と容量が部品表の大部分を占めるため、容量設計の規律が重要になります。\"}},{\"@type\":\"Question\",\"name\":\"小さく始めて後で拡張できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"はい。将来の負荷に合わせたサイズのインバーターから始め、時間をかけてアレイとバッテリーバンクを拡張してください。当社のインバーターのほとんどは、シリーズ内での並列拡張をサポートしています。\"}},{\"@type\":\"Question\",\"name\":\"自分の市場の正確な価格を知るにはどうすればよいですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"負荷リストと日照時間を当社の営業チームに共有してください — お問い合わせフォームを通じて、あなたの地域向けの最新の工場価格と構成オプションを提供します。\"}}]}</script>",
  },
  "pure-sine-wave-vs-modified-sine-wave": {
    title: "純正弦波インバーターと擬似正弦波インバーター：その違いとは？",
    description: "純正弦波インバーターと擬似正弦波インバーターの違い、純正弦波が必要な負荷、オフグリッドおよびバックアップシステムでの選び方を解説します。",
    tags: [
      "インバーターガイド",
      "太陽光の基礎",
      "オフグリッド",
    ],
    bodyHtml: "<p>純正弦波と擬似正弦波は、インバーターの仕様書で必ず目にする2つの出力波形です。違いは技術的に見えますが、どの家電が正しく動作するか — 時には動作するかどうかさえ — を左右します。</p>\n<h2>各波形の意味</h2>\n<p><strong>擬似正弦波</strong>（準正弦波と呼ばれることもあります）は、正弦波を階段状に近似したものです。製造コストが低く、白熱灯、ヒーター、基本的な工具などの抵抗負荷には問題ありません。</p>\n<p><strong>純正弦波</strong>は、電力会社の系統電源から供給される滑らかな正弦波ACを再現します。モーター、敏感なコントローラーを搭載した電子機器、トランスを内蔵する機器は、設計どおりに動作します。</p>\n<h2>純正弦波が必要な負荷は？</h2>\n<table>\n<thead>\n<tr>\n<th>負荷タイプ</th>\n<th>擬似正弦波</th>\n<th>純正弦波</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>白熱灯、ヒーター</td>\n<td>動作する</td>\n<td>動作する</td>\n</tr>\n<tr>\n<td>誘導モーター（ファン、ポンプ）</td>\n<td>過熱、騒音、効率低下のおそれ</td>\n<td>正常に動作</td>\n</tr>\n<tr>\n<td>冷蔵庫 / 冷凍庫</td>\n<td>コンプレッサー破損のリスク</td>\n<td>推奨</td>\n</tr>\n<tr>\n<td>テレビ、パソコン、充電器</td>\n<td>誤動作または発熱のおそれ</td>\n<td>推奨</td>\n</tr>\n<tr>\n<td>医療機器</td>\n<td>推奨されない</td>\n<td>推奨</td>\n</tr>\n<tr>\n<td>電子レンジ</td>\n<td>加熱が遅く、出力が低下</td>\n<td>フルパワーで動作</td>\n</tr>\n<tr>\n<td>可変速 / インバーター家電</td>\n<td>電子機器を損傷するおそれ</td>\n<td>推奨</td>\n</tr>\n</tbody>\n</table>\n<h2>実用的な影響</h2>\n<ul>\n<li><strong>モーターとコンプレッサー</strong>は、擬似正弦波では階段状の波形が高調波と熱を加えるため、より高温になり効率が低下します。</li>\n<li><strong>敏感な電子機器</strong>はリセット、ハム音、最悪の場合は故障するおそれがあります — 汚れた波形は制御基板に干渉することがあります。</li>\n<li><strong>オーディオ機器</strong>では可聴の電源ハムが乗ることがあります。</li>\n</ul>\n<h2>どちらを選ぶべきか</h2>\n<p>単純な抵抗負荷を超えるもの — 冷蔵庫、ポンプ、パソコン、テレビ、医療機器 — には、<strong>純正弦波インバーター</strong>が安全な既定の選択です。価格差はここ数年で大幅に縮まり、実際のプロジェクトでの信頼性の差は大きいです。</p>\n<p>当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>および<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>はすべて標準で純正弦波を出力するため、当社から調達する販売代理店や設置業者にとって波形の選択はすでに解決済みです。</p>\n<section aria-label=\"波形 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">波形 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">擬似正弦波インバーターは家電を損傷することがありますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">誘導モーターや一部の電子機器をより高温で動作させることで寿命を縮める可能性があります。損傷はすぐに起きるわけではありませんが、コンプレッサーや敏感な基板にとってリスクは現実にあります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">純正弦波は追加コストに見合いますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">冷蔵庫、ポンプ、パソコン、医療機器に電力を供給するシステムでは、はい。家電の故障やサービスコールのコストと比べれば、追加費用はわずかです。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">すべての純正弦波インバーターは同じ性能ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。効率、サージ能力、THD、信頼性は設計によって異なります。発注前に仕様表とメーカーの試験方法を確認してください。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"擬似正弦波インバーターは家電を損傷することがありますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"誘導モーターや一部の電子機器をより高温で動作させることで寿命を縮める可能性があります。損傷はすぐに起きるわけではありませんが、コンプレッサーや敏感な基板にとってリスクは現実にあります。\"}},{\"@type\":\"Question\",\"name\":\"純正弦波は追加コストに見合いますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"冷蔵庫、ポンプ、パソコン、医療機器に電力を供給するシステムでは、はい。家電の故障やサービスコールのコストと比べれば、追加費用はわずかです。\"}},{\"@type\":\"Question\",\"name\":\"すべての純正弦波インバーターは同じ性能ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。効率、サージ能力、THD、信頼性は設計によって異なります。発注前に仕様表とメーカーの試験方法を確認してください。\"}}]}</script>",
  },
  "paralleling-off-grid-inverters": {
    title: "オフグリッドインバーターを並列接続する方法：スマートに容量を倍増",
    description: "1台のインバーターでは足りない場合、同一のユニットを並列接続することでオフグリッド容量を2倍または3倍にできます。マスター・スレーブ構成、配線の対称性、試運転の実際の仕組みを解説します。",
    tags: [
      "インバーターガイド",
      "オフグリッド",
      "B2B",
    ],
    bodyHtml: "<p>1台のインバーターでは限界があります。プロジェクトがシリーズ最大のモデルを超える場合、あるいは予算の都合で「今は小さく始めて、後で拡張する」という場合、実用的な答えは多くの場合、2台以上の同一インバーターを並列運転することです。適切に行えば、並列バンクは1台のはるかに大きなユニットのように動作します。しかし、やり方を間違えると、煙が出たり、故障が発生したり、数週間のサービス時間を費やすことになります。</p>\n<p>このガイドでは、並列接続に実際に何が含まれるかを説明します。一致させる必要があるハードウェア、マスター・スレーブ調整の仕組み、負荷が均等に分担されるかどうかを決める配線ルール、そしてミスが故障になる前に捉える試運転手順です。</p>\n<blockquote>\n<p><strong>まず、正直な注意点:</strong> すべてのインバーターが並列接続をサポートしているわけではなく、制限はシリーズごとに異なります。特定のモデルが並列運転をサポートしているか、最大ユニット数、正確な配線と設定を、設計する前に必ずメーカーに確認してください。この記事は、お使いの特定のユニットのマニュアルに代わるものではありません。</p>\n</blockquote>\n<h2>並列接続が理にかなう場合</h2>\n<p>B2Bプロジェクトでは、次の3つのシナリオが繰り返し発生します：</p>\n<ul>\n<li><strong>段階的拡張。</strong> 顧客は今日の負荷に1台で始め、需要が増えたら2台目（または3台目）の同一ユニットを追加します。ケーブル1本と通信リンクを追加するだけで、ハードウェアを交換することなく、バンクが大きくなります。</li>\n<li><strong>在庫の簡素化。</strong> 販売店は単一の電力クラスを在庫し、同じSKUで1×、2×、3×のプロジェクトをカバーできます。いくつもの異なるモデルを倉庫に保管する必要はありません。</li>\n<li><strong>サービスの冗長性。</strong> 適切に構成されたバンクでは、故障したユニットをサイト全体をオフラインにすることなく隔離して交換できます（プラットフォームの故障動作を確認してください — ユニットの故障でシステム全体が停止するものもあります）。</li>\n</ul>\n<h2>並列接続できるものとできないもの</h2>\n<p>最も一般的な間違いは、ハードウェアを混在させることです。並列バンクが機能するのは、各ユニットが1つの共有リファレンスにロックされた波形を生成するためです。これは、ユニットが電気的および論理的に同一である場合にのみ機能します。</p>\n<ul>\n<li><strong>同じモデル、同じシリーズ</strong> — 必須。異なるモデル、電力クラス、あるいはハードウェアリビジョンの混在は、主流のプラットフォームではサポートされていません。</li>\n<li><strong>同じファームウェアバージョン</strong> — 強く推奨。混合ファームウェアで動作するバンクは、同期ハンドシェイクに失敗したり、負荷時にドリフトしたりする可能性があります。</li>\n<li><strong>同じDCシステム電圧</strong> — すべてのユニットが同じバッテリーバンク電圧を共有する必要があります（たとえばすべて48V）。</li>\n<li><strong>専用の同期リンク</strong> — マスターは、各ユニット間の通信ケーブルを介して位相と周波数を調整します。これはバッテリー通信ケーブルでは<em>ありません</em>。AC出力を位相を合わせるためのハートビートです。欠落または緩い場合、ユニットは並列接続を拒否するか、さらに悪いことに、試みて互いに電流を循環させます。</li>\n</ul>\n<p>住宅クラスのハイブリッドおよびオフグリッドプラットフォームの一般的なサポート範囲は2〜16ユニットで、実際の上限は通常、電子機器ではなくバッテリー電流とバスバーのサイズによって決まります。当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーターシリーズ</a>は900W〜5000W、<a href=\"/products/off-grid-solar-inverters/\">オフグリッドソーラーインバーターシリーズ</a>は最大11kWです。並列サポートがある場合、それは各シリーズ固有であり、複数ユニットの設計を見積もる前に確認する必要があります。</p>\n<h2>単相並列 vs スプリットフェーズ積み重ね</h2>\n<p>人々は「並列接続」という言葉を2つの異なるトポロジーに使用しており、それらを混同すると配線ミスを引き起こします：</p>\n<ul>\n<li><strong>真の並列接続</strong> は、同じフェーズにユニットを積み重ねてそのフェーズの電力を増やします — 同じ出力に3台の5kWユニットを接続すると、15kWの単相バンクになります。</li>\n<li><strong>スプリットフェーズ積み重ね</strong> は、2台のユニットを反対側のレッグ（L1とL2）に割り当てて、120/240Vのスプリットフェーズ電源を構築します。一部のプラットフォームは両方を行います：2つのレッグに各2台のユニットを配置して、高出力のスプリットフェーズシステムを構築します。</li>\n</ul>\n<p>配線する<em>前に</em>、プロジェクトにどのトポロジーが必要かを決定してください。ユニットメニューのフェーズ割り当ては、物理的な配線と正確に一致する必要があります。スプリットフェーズ構築では、負荷を接続する前にメーターで回転とレッグの割り当てを確認してください。</p>\n<h2>マスター・スレーブ調整とアドレッシング</h2>\n<p>1台のユニットが<strong>マスター</strong>として指定され、他のユニットがそれに従います。これは通常、各ユニットのメニューまたはDIPスイッチで設定され、アドレッシングルールは厳格です：</p>\n<ol>\n<li>すべてのユニットを並列有効モードに設定します。</li>\n<li>正確に1台のマスターを割り当て、各ユニットに<strong>一意のアドレス</strong>を付けます — 通常、マスターはユニット1で、スレーブは2、3、4…と番号付けられます。</li>\n<li>マスターは参照波形を生成し、同期リンクを介してブロードキャストします。スレーブはサイクルごとにそれにロックします。</li>\n<li>多くのプラットフォームでは、マスターはバッテリーBMSやエネルギーメーターとも通信するため、測定ポイントは1か所にあります — すべてのユニットにメータリングを配線しないでください。そうしないと測定値が互いに競合します。</li>\n</ol>\n<p>これらの手順をいずれか省略すると、バンクは起動を拒否するか、不均一で不安定な出力で動作します。</p>\n<h2>DC側：1つのバッテリーバス、対称的に配線</h2>\n<p>DC側は、ほとんどの並列システムの問題が生じる場所です。経験則：<strong>すべてのユニットは1つの共通バッテリーバスに接続し、各ユニットへのすべてのケーブルは同じ長さ、種類、断面積である必要があります。</strong></p>\n<p>対称性が重要な理由：バッテリーケーブルはバンク全体の電流を運び、ユニットAのケーブルがユニットBより0.5メートル短い場合、その低い抵抗により多くの電流を供給し、より多くの負荷がかかります。解決策はより太いケーブルではなく、すべてのユニットに<em>等しい</em>ケーブルを使用し、ユニット間でデイジーチェーン接続するのではなく、共通のバスバーに接続することです。</p>\n<p>簡単な目安：48Vバンクの5kWインバーターは、全負荷時に約104Aを消費するため、3ユニットのバンクはバッテリーから300A以上を引き出す可能性があります。バスバーとケーブルは合計電流に合わせてサイズを決定し、各ユニットを個別にヒューズ保護し、すべてのラグをマニュアルの仕様に従ってトルクで締めてください。</p>\n<p>バッテリー戦略は2つあります：</p>\n<ul>\n<li><strong>共有バッテリーバンク</strong> — 最もシンプルで安価、BMSとの通信は1回。バンク全体が1つの容量プールから電力を引き出します。</li>\n<li><strong>ユニットごとの独立バンク</strong> — 冗長性が高い（1つのバンクの故障が他に影響しない）が、機器と個別管理が増えます。プラットフォームがバッテリー共有の無効化をサポートしている場合にのみ有効です。</li>\n</ul>\n<h2>AC側：共通負荷バス、1つの接地結合</h2>\n<p>AC側では、バックアップ負荷は<strong>共通負荷バスバー</strong>に接続され、各ユニットの出力には個別の保護が設けられます。マルチインバーターサイトの重要な安全規則：<strong>中性線とアースの結合は正確に1か所に存在する必要があります。</strong> 複数のユニットがある場合、マスター（または転送ポイント）のみが結合を保持していることを確認してください — 並列バンク内の2つの結合は、循環接地電流と危険な電圧不平衡を引き起こします。</p>\n<p>発電機入力が装備されている場合は、すべての並列ユニットがそれを認識できるように接続する必要があり、相回転はインバーターのプログラムと一致する必要があります。</p>\n<h2>煙を防ぐ試運転シーケンス</h2>\n<p>並列バンクの起動は、通常の起動に手順を追加します：</p>\n<ol>\n<li><strong>最初に各ユニットを単独で起動</strong>し、エラーなしで単独運転することを確認します。</li>\n<li>すべての電源を切り、同期ケーブルを接続し、マスター/スレーブの役割とアドレッシングを設定します。</li>\n<li><strong>マスターを最初に</strong>起動し、次にスレーブを起動します。</li>\n<li>バンクが稼働し、<strong>負荷がない状態</strong>で、すべてのユニットが同じ周波数と電圧を報告することを確認します。</li>\n<li>テスト負荷を適用し、分担を確認します — 2台のユニットはそれぞれほぼ半分を負担するはずで、80/20ではありません。不均一な分担は、健全なバンクではなく、同期または設定の問題を示しています。</li>\n<li>実際の負荷で最初の丸1日はサイトを観察下に置きます。アイドル時に隠れている不平衡は、工房や家庭が朝のピークを迎えるときによく現れます。</li>\n</ol>\n<h2>並列接続すべきでない場合</h2>\n<p>並列接続はコスト、配線、故障モードを追加します。1台のユニットがサージに対する余裕を持って負荷をカバーできる場合、またはプロジェクトが三相出力を本当に必要とする場合、適切にサイズ設定された単一ユニット（または三相プラットフォーム）が通常はより良い選択です。並列バンクがその価値を発揮するのは、プロジェクトが<strong>設計上将来拡張可能</strong>な場合です — 今日は1台、明日は2台または3台。</p>\n<section aria-label=\"並列接続 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">並列接続 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">異なるインバーターモデルを2台並列接続できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。並列接続するユニットは同じモデルである必要があり、理想的には同じファームウェアバージョン、同じDCシステム電圧である必要があります。不一致のユニットは、同期ハンドシェイクに失敗したり、負荷時にドリフトしてトリップする可能性があります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">何台のインバーターを並列接続できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">プラットフォームによります — 一般的な住宅クラスのユニットは2〜16台の並列接続をサポートしています。実際の制限は通常、バッテリーバンクの連続電流定格とバスバーのサイズによって決まり、すべてのユニットを一度に処理できる必要があります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">インバーターを並列接続するには特別なケーブルが必要ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">はい — 専用の同期ケーブル（多くの場合RJ45/CAN）が各ユニット間に配線され、マスターからの位相と周波数のハートビートを伝えます。これはバッテリー通信ケーブルとは別です。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">すべてのインバーターが並列接続をサポートしていますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。並列サポートはシリーズごとの機能です。システムを設計する前に、正確なモデルが並列運転をサポートしているか、最大ユニット数、必要な設定をメーカーに確認してください。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"異なるインバーターモデルを2台並列接続できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。並列接続するユニットは同じモデルである必要があり、理想的には同じファームウェアバージョン、同じDCシステム電圧である必要があります。不一致のユニットは、同期ハンドシェイクに失敗したり、負荷時にドリフトしてトリップする可能性があります。\"}},{\"@type\":\"Question\",\"name\":\"何台のインバーターを並列接続できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"プラットフォームによります — 一般的な住宅クラスのユニットは2〜16台の並列接続をサポートしています。実際の制限は通常、バッテリーバンクの連続電流定格とバスバーのサイズによって決まり、すべてのユニットを一度に処理できる必要があります。\"}},{\"@type\":\"Question\",\"name\":\"インバーターを並列接続するには特別なケーブルが必要ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"はい — 専用の同期ケーブル（多くの場合RJ45/CAN）が各ユニット間に配線され、マスターからの位相と周波数のハートビートを伝えます。これはバッテリー通信ケーブルとは別です。\"}},{\"@type\":\"Question\",\"name\":\"すべてのインバーターが並列接続をサポートしていますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。並列サポートはシリーズごとの機能です。システムを設計する前に、正確なモデルが並列運転をサポートしているか、最大ユニット数、必要な設定をメーカーに確認してください。\"}}]}</script>",
  },
  "inverter-power-derating-temperature-altitude": {
    title: "インバーターの出力ディレーティング：熱・標高・気流が定格ワット数を減らす理由",
    description: "定格ワット数は海抜0m・25°Cで測定されます。実際の設置現場はより高温で、より高標高です。温度ディレーティング、標高ディレーティング、冷却設計が実際に使用可能な電力をどのように削減するか、そして現実に即した選定方法を解説します。",
    tags: [
      "インバーターガイド",
      "選定ガイド",
      "B2B",
    ],
    bodyHtml: "<p>すべてのインバーターの箱には、3000W、5000W、11kW といった数字が記載されています。しかし、その数字は実験室条件 — 通常は周囲温度25°C、海抜0m、本体周囲に自由な気流がある状態 — で測定されたものです。同じインバーターを45°Cの環境にある通気性のある通信キャビネット内に設置したり、標高3000mの屋上サイトに設置したりした場合、「実際に一日中どれだけの電力を供給できるのか？」という問いに対する正直な答えは、通常、銘板に記載された値より小さくなります。</p>\n<p>これはB2B購入者にとって最も重要です。容量不足は現場で、過負荷トリップ、ファンの早期故障、怒り心頭のエンドユーザーとして現れるからです。本ガイドでは、実効電力を低下させる3つの要因 — 温度、標高、気流 — と、ディレーティング曲線の読み方、そして現場環境が厳しくなっても定格ワット数を供給できるシステムのサイジング方法を説明します。</p>\n<blockquote>\n<p><strong>数値に関する注記。</strong> 以下のディレーティング数値は、一般的なデータシートの挙動から抽出した業界の典型的なパターンであり、特定のモデルの仕様ではありません。必ず、購入予定ユニットのデータシートに記載された実際のディレーティング曲線に基づいてサイジングしてください。メーカーがそれを公開しない場合は、危険信号と見なしてください。</p>\n</blockquote>\n<h2>銘板ワット数が実験室で測定される理由、プロジェクト現場ではない理由</h2>\n<p>標準化団体は、インバーター定格の基準条件を定義しています。周囲温度25°C、海抜0m、妨げのない空気の流れ、そして多くの場合、特定のDC入力電圧です。その基準点では、ユニットは連続定格出力を無期限に供給できます。</p>\n<p>現場条件は、予測可能な形でその基準から逸脱します：</p>\n<ul>\n<li><strong>周囲の熱</strong> はパワー半導体の温度を上昇させ、寿命を短縮し、ファームウェアに保護のため出力を絞らせます。</li>\n<li><strong>標高</strong> は空気を薄くするため、ヒートシンクとファンが1秒あたりに運び去れる熱量が減ります。</li>\n<li><strong>密閉または積み重ね設置</strong> は気流を遮り、インバーター自身の排熱を閉じ込めます。</li>\n<li><strong>バッテリー電圧の低下や、入力窓の端に近いPV入力</strong> も供給可能電力を削減しますが、これは本記事で扱う熱的要因とは別のディレーティング軸です。</li>\n</ul>\n<p>これはメーカーが不正をしているわけではありません。定格とは基準条件に関する表明であり、購入者または設計者であるあなたの仕事は、銘板の数値を実際の現場の数値に置き換えることです。</p>\n<h2>温度ディレーティング：最も一般的な電力損失</h2>\n<p>パワー半導体と磁気部品は、出力電力におおむね比例する熱を発生します。特定の内部接合部温度向けに設計されたインバーターは、周囲の空気がすでに高温の場合、排熱を押し出すための温度差が小さくなるため、全出力を維持できません。</p>\n<p>オフグリッドおよび住宅用ハイブリッドインバーターに一般的に見られるディレーティングパターンは次のとおりです：</p>\n<table>\n<thead>\n<tr>\n<th>周囲温度</th>\n<th>利用可能な連続出力（典型的なパターン）</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>25°C (77°F)</td>\n<td>定格の100%</td>\n</tr>\n<tr>\n<td>40°C (104°F)</td>\n<td>定格の85～95%</td>\n</tr>\n<tr>\n<td>45°C (113°F)</td>\n<td>定格の75～85%</td>\n</tr>\n<tr>\n<td>50°C (122°F)</td>\n<td>定格の60～75%</td>\n</tr>\n<tr>\n<td>55°C (131°F)</td>\n<td>定格の50～65%</td>\n</tr>\n</tbody>\n</table>\n<p>あらゆるデータシートを妥当性確認するために知っておくべき2つのパターンがあります：</p>\n<ol>\n<li><strong>「サーマルニー」までは全出力。</strong> 多くのユニットは40°Cまで100%出力を維持し、それを超えると初めて低減し始めます。データシートに「40°Cでの連続出力」と記載されている場合、それはそのニーがどこにあるかを示しています。</li>\n<li><strong>ニーより上では線形に低下。</strong> ニーを超えると、出力は通常、温度に対して直線的に低下し、ユニットが最大定格周囲温度に達すると保護シャットダウンします。傾きは、高温気候がどれほどのコストになるかを示します。</li>\n</ol>\n<p>熱帯プロジェクト — ナイジェリア、インド、タイ、湾岸諸国など — では、関連する数値は通常25°Cの列ではなく、40～45°Cの列です。</p>\n<h2>標高ディレーティング：薄い空気は熱を運びにくい</h2>\n<p>ヒートシンクとファンは空気を動かして冷却します。標高が高いほど空気密度が低くなるため、1立方メートルあたりの気流が運び去れる熱量が減り、ファンはより少ない冷却のために多くの仕事をします。そのため、ほとんどのインバーターは2000m以下で認証・定格されており、それを超えるとディレーティングします。</p>\n<p>データシートに見られる典型的な規則：2000mを超えると、標高が<strong>100m増えるごとに出力が約0.5～1%失われる</strong>と見積もってください。これは次のようになります：</p>\n<ul>\n<li>2500m地点：定格出力の約97～100%。</li>\n<li>3000m地点：定格出力の約90～95%。</li>\n<li>4000m地点：定格出力の約80～90% — 特定のモデルを確認してください。</li>\n</ul>\n<p>高標高プロジェクト — アンデス、ヒマラヤ、東アフリカ、メキシコ中部のサイト — では、標高係数と温度係数を組み合わせてください。山間サイトは日中、標高が高い<em>うえに</em>高温であることが多く、2つのディレーティングは加算ではなく乗算で複合するためです。</p>\n<h2>冷却設計：メーカーがこの熱にどう対処しているか</h2>\n<p>ディレーティングは安全弁ですが、優れた熱設計はニーを高くするため、安全弁が開くことはほとんどありません。ユニットを評価するときは、熱がどのように外部へ逃げるかに注目してください：</p>\n<ul>\n<li><strong>ファン制御冷却。</strong> ほとんどのユニットは温度制御ファンを使用し、低負荷時は停止（または低速）し、ヒートシンクが温まると高速化します。当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>ラインの全モデルには、インテリジェントな温度制御ファンが搭載されており、アイドル時の騒音を抑え、連続出力時に部品を保護します。</li>\n<li><strong>ヒートシンクと筐体の材質。</strong> アルミニウム筐体は、より広い表面に熱を分散します。当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>の一部モデルでは、放熱を目的としてアルミニウム合金ケースを明示的に採用しています。</li>\n<li><strong>ファン故障検出。</strong> ファンが故障したことを知らせられないユニットは、誰かが気づくまで静かにディレーティングする — あるいは過熱する — ユニットです。過温度保護と故障報告機能を備えたモデルを選んでください。</li>\n<li><strong>ディレーティング曲線の公開。</strong> 最も優れた調達シグナルは、メーカーがデータシートに温度/標高ディレーティング表を公開していることです。記載がなければ、請求してください。</li>\n</ul>\n<p>設置方法はハードウェアと同じくらい重要です。メーカー推奨のクリアランスをユニット周囲に確保し、通気口をふさがず、ユニットを直上に積み重ねることを避け、インバーター自身の排気が別のユニットの吸気口に吹き込むような設置は絶対に行わないでください。</p>\n<h2>連続出力とサージ：どちらも実際の数値</h2>\n<p>「どのワット数が重要か」という話題のついでに、インバーターが実際に持つ2つの定格を分けて考えましょう：</p>\n<ul>\n<li><strong>連続定格</strong> — 明示された周囲温度で、ユニットが何時間も供給できる電力。これがディレーティングする数値です。</li>\n<li><strong>サージ（ピーク）定格</strong> — モーター、コンプレッサー、ポンプを始動するために数秒間利用できる電力。サージ能力は短時間であるため、熱ディレーティングとはほぼ無関係ですが、有限でもあります。倍率（高周波ユニットでは通常連続の2～3倍、低周波設計ではそれ以上）と持続時間の両方を確認してください。</li>\n</ul>\n<p>連続負荷は、現場の最悪周囲温度における<em>ディレーティング後</em>の連続値に対してサイジングし、始動サージはサージ値に対してサイジングしてください。この2つを混同すると、「紙の上では問題ない」システムが初日にトリップすることになります。</p>\n<h2>簡易ワークシート：定格ワット数を現場ワット数に変換する</h2>\n<p>一次概算では、銘板値に2つの熱係数と必要な力率の余裕を掛けます：</p>\n<p><strong>実効連続電力 ≈ 定格 × 温度係数 × 標高係数</strong></p>\n<p>計算例 — 45°Cに達し、標高2200mにある現場で、通気性のある筐体内に設置された5000Wオフグリッドインバーター：</p>\n<ul>\n<li>45°Cでの温度係数（典型的な中間レンジのパターン）：約0.80</li>\n<li>2200mでの標高係数（2000mのしきい値を200m超過、約1%/100m）：約0.98</li>\n<li>実効連続電力 ≈ 5000 × 0.80 × 0.98 ≈ <strong>3920W</strong></li>\n</ul>\n<p>したがって、設計ではこのユニットをその現場における約4kWの連続電源として扱うべきです — 箱には5000Wと書かれていても。プロジェクトのピーク連続負荷が4.5kWの場合、このユニットは容量不足であり、正直な解決策はより大きなモデル、より涼しい設置場所、またはその両方です。</p>\n<p>同じ論理はラインナップ全体に当てはまります。当社の<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーターライン</a>は基準条件で最大11kWですが、高温の屋根裏空間に設置された10.5kWまたは11kWモデルは、最も暑い時間帯にかなり少ない電力を供給します — アレイ、負荷、インバーターは、銘板値ではなく<em>ディレーティング後</em>の数値が負荷を上回るようにサイジングしてください。</p>\n<h2>B2Bチェックリスト：見積もり前に確認すべき質問</h2>\n<p>転売または大規模設置のためにインバーターを購入する場合は、これらを選定リストに追加してください：</p>\n<ol>\n<li><strong>40°Cおよび45°Cでの連続出力はいくらですか？</strong> 答えが「25°Cと同じ」である場合は、印刷された曲線で確認してください — 40°Cまで本当に全出力を維持するユニットもあれば、悪い知らせを単に省いているものもあります。</li>\n<li><strong>最大周囲温度定格を超えるとどうなりますか？</strong> クリーンな熱シャットダウンですか、それともエンドユーザーをいらだたせる繰り返しトリップですか？</li>\n<li><strong>ディレーティングはどの標高から始まり、100mあたりどれくらいですか？</strong></li>\n<li><strong>設置マニュアルではどのようなクリアランスと換気が要求されていますか？</strong></li>\n<li><strong>ヒートシンクに温度センサーはありますか？ファン故障保護はありますか？</strong></li>\n<li><strong>ユニットは内部温度を報告しますか</strong>（ディスプレイまたは遠隔監視経由で）、高温サイトを故障発生前に把握できますか？</li>\n</ol>\n<p>銘板値だけで購入することは、ディストリビューター在庫が現場故障に変わる道です。ディレーティング曲線に基づいて購入することは、プロジェクトが7月に — そして3000m地点で — 約束を守る方法です。</p>\n<section aria-label=\"インバーターの電力ディレーティング — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">インバーターの電力ディレーティング — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">すべてのインバーターは高温時にディレーティングしますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">ほとんどはディレーティングします。パワー半導体には最大接合部温度があるためです。40°Cまで全出力を維持し、それを超えると初めて低減するユニットもあります。正確なニーと傾きはモデル固有であり、データシートのディレーティング曲線から読み取る必要があります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">インバーターはどの標高からディレーティングを始めますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">一般的な認証しきい値は2000mです。それを超えると、標高が100m増えるごとに出力が約0.5～1%失われると見積もってください。薄い空気はヒートシンクとファンから運び去れる熱量が減るためです。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">サージ電力は温度や標高の影響を受けますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">サージ定格は短時間であるため、熱ディレーティングとはほぼ無関係です — 熱容量が短時間の熱を吸収します。ただし、サージ能力は倍率と持続時間の両方で依然として有限であるため、最悪の始動負荷に対して両方の数値を確認してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">高温・高標高の現場では、インバーターをどれくらい大きく選定すべきですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">普遍的な数値はありません。現場の最悪条件における温度係数と標高係数を銘板値に掛け、ディレーティング後の連続出力がピーク連続負荷を余裕をもって上回るモデルを選んでください。現場が非常に高温の場合、より大きなモデル、またはより涼しく換気の良い設置場所の方が、ファームウェア保護に頼るよりも通常は優れています。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"すべてのインバーターは高温時にディレーティングしますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"ほとんどはディレーティングします。パワー半導体には最大接合部温度があるためです。40°Cまで全出力を維持し、それを超えると初めて低減するユニットもあります。正確なニーと傾きはモデル固有であり、データシートのディレーティング曲線から読み取る必要があります。\"}},{\"@type\":\"Question\",\"name\":\"インバーターはどの標高からディレーティングを始めますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"一般的な認証しきい値は2000mです。それを超えると、標高が100m増えるごとに出力が約0.5～1%失われると見積もってください。薄い空気はヒートシンクとファンから運び去れる熱量が減るためです。\"}},{\"@type\":\"Question\",\"name\":\"サージ電力は温度や標高の影響を受けますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"サージ定格は短時間であるため、熱ディレーティングとはほぼ無関係です — 熱容量が短時間の熱を吸収します。ただし、サージ能力は倍率と持続時間の両方で依然として有限であるため、最悪の始動負荷に対して両方の数値を確認してください。\"}},{\"@type\":\"Question\",\"name\":\"高温・高標高の現場では、インバーターをどれくらい大きく選定すべきですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"普遍的な数値はありません。現場の最悪条件における温度係数と標高係数を銘板値に掛け、ディレーティング後の連続出力がピーク連続負荷を余裕をもって上回るモデルを選んでください。現場が非常に高温の場合、より大きなモデル、またはより涼しく換気の良い設置場所の方が、ファームウェア保護に頼るよりも通常は優れています。\"}}]}</script>",
  },
  "lithium-battery-inverter-compatibility": {
    title: "あらゆるリチウム電池はインバーターで動作するのか？電圧、充電、BMS通信を解説",
    description: "リチウム電池はインバーターの電圧に適合していても、正しく動作しないことがあります。電圧範囲、充電プロファイル、BMS通信（CAN/RS485）が、電池とインバーターのペアが実際に機能するかを左右します。",
    tags: [
      "バッテリー互換性",
      "BMS通信",
      "オフグリッド",
    ],
    bodyHtml: "<p>理論上は、リチウム電池をインバーターに接続するのは簡単です。公称電圧を合わせ、ケーブルを選定し、ブレーカーを閉じるだけです。しかし実際には、「適合する」電池でも、誤った放電をしたり、放電中に停止したり、変動する充電状態を報告したりすることがあります。それは、3つの別々の互換性レイヤーが同時に一致する必要があるからです。</p>\n<p>本ガイドでは、これら3つのレイヤー — 電圧ウィンドウ、充電プロファイル、BMS通信 — を順に解説します。これにより、出荷<em>前</em>に電池とインバーターのペアを適格性評価できます。顧客の壁で故障してからでは遅いのです。</p>\n<h2>レイヤー1：電圧ウィンドウ</h2>\n<p>「48 V」電池は実際には48 Vではありません。48 VのLiFePO4パックは、満充電で約58.4 Vから、ほぼ空の状態で約40 Vまで変化します。12 Vパックは14.6 Vから約10 Vまで変化します。インバーターのDC入力ウィンドウは、公称点だけでなく、<em>全</em>範囲をカバーする必要があります。</p>\n<p>ウィンドウが間違っていると、2つの故障モードが現れます：</p>\n<ul>\n<li><strong>過電圧カットオフ。</strong> パックがインバーターの最大DC入力を超えて充電されると、電池が満充電に達するたびにインバーターがトリップまたは故障します — システムが最も静かであるべき時に。</li>\n<li><strong>低電圧シャットダウン。</strong> インバーターの低DCカットオフが電池自体の空電圧より高い場合、パックに使用可能なエネルギーが残っているのにインバーターがシャットダウンします。顧客はこれを「電池が30%で死ぬ」と見ます。</li>\n</ul>\n<p>実用的なルール：両方のデータシートを読み、電池の満充電電圧がインバーターの最大DC入力より低いこと、および電池の保護カットオフがインバーターの最小値より高いことを確認します。両側に1～2 Vのマージンを残します。</p>\n<p>当社の<a href=\"/products/off-grid-inverters/\">オフグリッドインバーター</a>は広いDC入力ウィンドウを備えています — シリーズ全体で12 V / 24 V / 48 V / 60 V / 72 V — したがって、電池が変わったときに新しいインバーターの購入を強制するのではなく、1つのモデルを異なるバンク構成に適合させることができます。<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーターシリーズ</a>は、統合MPPTコントローラーを備えた固定12 V、24 V、48 Vバンクをカバーし、各製品ページの仕様表に正確なDC入力範囲が記載されています。</p>\n<h2>レイヤー2：充電プロファイル</h2>\n<p>電圧互換性はシステムを動作させますが、充電プロファイルが電池の定格サイクル寿命を全うできるかを決定します。</p>\n<table>\n<thead>\n<tr>\n<th>パラメータ</th>\n<th>設定場所</th>\n<th>無視した場合の問題</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>吸収 / 充電電圧</td>\n<td>インバーター充電器メニュー</td>\n<td>高すぎると、BMSが過電圧で切断します。低すぎると、バンクが100%に達しません</td>\n</tr>\n<tr>\n<td>充電電流制限</td>\n<td>電池BMS → インバーター</td>\n<td>セル定格を超える電流はパックを過熱させ、早期に劣化させます</td>\n</tr>\n<tr>\n<td>フロート電圧</td>\n<td>インバーター充電器メニュー</td>\n<td>リチウムを鉛蓄電池のフロート電圧に保持すると、セルに無意味な高ストレスを与えます</td>\n</tr>\n<tr>\n<td>温度カットオフ</td>\n<td>電池BMS</td>\n<td>0 °C未満での充電はアノードにリチウムをメッキし、永久容量損失を引き起こします</td>\n</tr>\n</tbody>\n</table>\n<p>典型的な間違いは、インバーターの工場出荷時のデフォルトをそのままにすることです。これらは通常、鉛蓄電池用に調整されています。たとえば、「12 V」バンクに13.8 Vのフロート電圧などです。LiFePO4はフロートを全く必要としません — 充電後、休止を必要とします。インバーターメニューにリチウム電池タイプがある場合はそれを選択します。ない場合は、吸収電圧とフロート電圧を電池のデータシートに記載された値に設定し、試運転後にメーターで確認します。</p>\n<h2>レイヤー3：BMS通信</h2>\n<p>最新のリチウムパックは、セル電圧、電流、温度を監視する電池管理システムを搭載しており、そのBMSは<strong>CANバス</strong>または<strong>RS485</strong>を介してインバーターと通信できます。リンクが有効な場合、インバーターは継続的な指示を受け取ります。正確な充電電圧、<em>現在</em>の電流制限（セルが低温または不平衡のときに縮小する）、真の充電状態、およびアラームです。</p>\n<p>リンクがないか不一致の場合、インバーターは固定の手動設定にフォールバックします — そして4つの症状が現れます：</p>\n<ol>\n<li><strong>SOCドリフト。</strong> インバーターがBMSを読み取る代わりに電圧から推測するため、負荷が落ちる一方でディスプレイは60%を示します。</li>\n<li><strong>充電拒否。</strong> BMSが熱的理由で電流を制限しますが、インバーターはそれを知らずに、BMSが切断するまで全電流を流し続けます。</li>\n<li><strong>使用中のシャットダウン。</strong> 保護イベントが発生してもインバーターに伝わらないため、システムは警告や記録された故障なしに停止します。</li>\n<li><strong>サイレントアラーム。</strong> 高温または過電流フラグは、監視アプリで表示されないままになります。</li>\n</ol>\n<p>微妙な落とし穴：物理的に適合するCANプラグは、プロトコルが一致することを意味しません。CANはビットがワイヤ上をどのように移動するかを定義します。<em>メッセージマップ</em> — どのレジスタがSOCを保持し、どれが充電制限を保持するか — がブランドで分かれるところです。常に、電池のプロトコルプロファイルがインバーターで明示的にサポートされていることを確認し、見た目が同じ既製のケーブルではなく、メーカーのピン配列を使用してください。</p>\n<h3>通信と手動設定の比較</h3>\n<table>\n<thead>\n<tr>\n<th>項目</th>\n<th>BMS通信</th>\n<th>手動電圧設定</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>充電状態</td>\n<td>BMSから直接読み取り</td>\n<td>電圧から推定</td>\n</tr>\n<tr>\n<td>電流制限</td>\n<td>動的、温度に追従</td>\n<td>固定値</td>\n</tr>\n<tr>\n<td>保護応答</td>\n<td>調整された警告後にシャットダウン</td>\n<td>インバーターが盲目的にトリップ</td>\n</tr>\n<tr>\n<td>保証の位置づけ</td>\n<td>リチウムでは通常必須</td>\n<td>多くの場合除外</td>\n</tr>\n</tbody>\n</table>\n<p>顧客向けの設置では、通信をオプションではなく必須として扱ってください。手動設定は、ベンチテストや保守的な制限での緊急代替として許容されます。</p>\n<h2>購入前チェックリスト</h2>\n<p>電池とインバーターの組み合わせの発注書を発行する前に、このリストを実行してください：</p>\n<ul class=\"contains-task-list\">\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 電池の満充電電圧 &#x3C; インバーターの最大DC入力（≥ 1 Vのマージンあり）</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 電池の保護カットオフ > インバーターの最小DC入力（≥ 1 Vのマージンあり）</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> インバーターの最大充電電流 ≤ 電池BMSの連続充電定格</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> インバーターの最大放電電流 ≤ 電池BMSの連続放電定格</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> プロトコルプロファイル（CANまたはRS485）が両側でサポートされていると明示されている</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 通信ケーブルのピン配列がメーカーのドキュメントに準拠している</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 充電パラメータが書面で入手可能（吸収、フロート、カットオフ）</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> 1回のベンチテスト：満充電、満放電、両端でSOC表示を追跡</li>\n</ul>\n<p>最後の項目は午後を費やしますが、最も高価なクラスの現場故障 — 倉庫では動作するが顧客の壁で誤動作するシステム — を防ぎます。</p>\n<h2>当社の電池ペアリングサポート</h2>\n<p>電池の互換性に関する質問は、当社のセールスエンジニアリングデスクに毎日届きます。当社のB2B顧客のほとんどが、サードパーティの電池ブランドをプロジェクトに統合しているためです。当社のプラットフォームでは、2つのことがそれを容易にします：</p>\n<ul>\n<li><strong>広く文書化されたDC入力ウィンドウ。</strong> <a href=\"/products/off-grid-inverters/\">オフグリッドインバーターシリーズ</a>は900 Wから5000 Wまで、12～72 Vの入力オプションを備え、<a href=\"/products/off-grid-solar-inverters/\">MPPT内蔵太陽光インバーターシリーズ</a>は12 V、24 V、48 Vバンクを最大11 kWのPV入力までカバーします — したがって、インバーターが電池に適応し、その逆ではありません。</li>\n<li><strong>試運転サポート。</strong> 当社のエンジニアは、出荷前に特定の電池モデルの充電パラメータと通信設定を確認します。<a href=\"/contact/\">お問い合わせフォーム</a>からペアリングを送信していただければ、設定を書面で確認します。</li>\n</ul>\n<section aria-label=\"電池とインバーターの互換性 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">電池とインバーターの互換性 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">鉛蓄電池用に設計されたインバーターにリチウム電池を接続できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">多くの場合可能ですが、充電電圧をリチウムのデータシート値に手動で設定し、DC入力ウィンドウがパックの満充電電圧をカバーしている必要があります。ただし、BMS通信がないと、正確なSOC、動的電流制限、調整されたアラームが失われるため、第一選択ではなくフォールバックとして扱ってください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">CANケーブルが適合してもプロトコルが異なる場合はどうなりますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">物理リンクは初期ハンドシェイクを通過することさえありますが、その後サイレントに失敗します — SOCは凍結したまま、充電制限は更新されない、またはファームウェア更新が後でリンクを壊します。互換性を決定するのは、コネクタではなく、プロトコル内のメッセージマップです。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">BMSはヒューズやブレーカーを置き換えますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。BMSは電子的にセルを保護しますが、外部ヒューズとDCブレーカーはケーブルを保護し、故障電流を遮断します。準拠した設置には両方が必要です。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">1つのバンクで電池ブランドを混ぜてインバーターと通信できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。並列電池は、BMSユニットが負荷を均等に分担するために、同じモデル、ファームウェア、年齢である必要があります。混合バンクは、循環電流、SOCの不一致、早期のBMS切断として現れます。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"鉛蓄電池用に設計されたインバーターにリチウム電池を接続できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"多くの場合可能ですが、充電電圧をリチウムのデータシート値に手動で設定し、DC入力ウィンドウがパックの満充電電圧をカバーしている必要があります。ただし、BMS通信がないと、正確なSOC、動的電流制限、調整されたアラームが失われるため、第一選択ではなくフォールバックとして扱ってください。\"}},{\"@type\":\"Question\",\"name\":\"CANケーブルが適合してもプロトコルが異なる場合はどうなりますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"物理リンクは初期ハンドシェイクを通過することさえありますが、その後サイレントに失敗します — SOCは凍結したまま、充電制限は更新されない、またはファームウェア更新が後でリンクを壊します。互換性を決定するのは、コネクタではなく、プロトコル内のメッセージマップです。\"}},{\"@type\":\"Question\",\"name\":\"BMSはヒューズやブレーカーを置き換えますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。BMSは電子的にセルを保護しますが、外部ヒューズとDCブレーカーはケーブルを保護し、故障電流を遮断します。準拠した設置には両方が必要です。\"}},{\"@type\":\"Question\",\"name\":\"1つのバンクで電池ブランドを混ぜてインバーターと通信できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。並列電池は、BMSユニットが負荷を均等に分担するために、同じモデル、ファームウェア、年齢である必要があります。混合バンクは、循環電流、SOCの不一致、早期のBMS切断として現れます。\"}}]}</script>",
  },
  "mppt-voltage-window-pv-string-sizing": {
    title: "MPPT電圧ウィンドウ：オフグリッドインバーターに太陽光アレイをマッチングする方法",
    description: "最大PV電圧、MPPT動作範囲、入力電力は3つの異なる制限です。寒い朝でもアレイが耐え、暑い午後でもトラッキングするようにストリングを設計する方法。",
    tags: [
      "MPPT",
      "サイジングガイド",
      "オフグリッド",
    ],
    bodyHtml: "<p>多くのオフグリッドインバーターが太陽光アレイを「拒否」するのは、ワット数を拒否しているわけではありません。アレイは紙の上では十分な電力を生成しますが、最初の寒く晴天の朝、開放電圧がインバーターの入力上限を超えたり、暑い屋根でストリング電圧がMPPTの下限を下回ったりすると、充電ステージが単に動作を停止します。PV入力のサイジングは、電力の問題である前に電圧の問題です。</p>\n<p>このガイドでは、すべてのデータシートが公表している3つの制限、なぜ寒冷気候が最も危険な制限を動かすのか、そして自社プラットフォームの実例を使ってストリング計算を実行する方法を説明します。</p>\n<h2>3つの制限、3つの異なる数値</h2>\n<p>オフグリッドインバーターの太陽光入力は3つの別々の数値によって管理され、それらを混同することがほとんどのサイジングミスの根本原因です：</p>\n<table>\n<thead>\n<tr>\n<th>制限</th>\n<th>適用される電圧</th>\n<th>超えた場合にどうなるか</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>最大PV入力電圧</td>\n<td>開放電圧（Voc）</td>\n<td>入力段の永久損傷 — 保証対象外</td>\n</tr>\n<tr>\n<td>MPPT動作範囲</td>\n<td>動作電圧（Vmp）</td>\n<td>トラッキングが劣化または停止し、出力が急激に低下</td>\n</tr>\n<tr>\n<td>最大PV入力電力</td>\n<td>アレイの合計ワット数</td>\n<td>過剰な電力はクリップされ、インバーターは決してそれを使用しない</td>\n</tr>\n</tbody>\n</table>\n<p>最初の制限はハードウェアを破壊するものです。開放電圧は、入力段が電流を引き込む<em>前に</em>見るものです — 夜明けや、ブレーカーが閉じた瞬間です。ストリング設計以外にそれを保護するものはありません。2番目の制限は効率の境界です：ウィンドウの外ではトラッカーが動作点を見つけられず、コンポーネントが損傷していなくても充電が崩壊します。3番目は最も穏やかです — 過大なアレイは無駄な出費であり、ハードウェアの破損ではありません。</p>\n<p>各制限が異なる数値に適用されるため、有効な設計は3つの独立したチェックを通過する必要があります。1つを通過しても、他の2つについては何も証明されません。</p>\n<h2>寒い朝のVocの罠</h2>\n<p>モジュールのデータシートは、セル温度25°CでのVocを記載しています。実際の動作では、セルが冷えるにつれて開放電圧が上昇します — 通常、1度あたり約0.25～0.30%です。49VのVoc定格のパネルは、霜の降りた朝には54Vをはるかに超える値を示すことがあり、その日の最高電圧は太陽がアレイに負荷をかける<em>前に</em>訪れ、まさに入力段が最も露出する時です。</p>\n<p>補正は簡単な算術です：銘板のVocに、<code>1 + 0.0027 × (25 − T_min)</code> の寒冷係数を掛けます。ここで <code>T_min</code> は、そのサイトの記録最低セル温度（°C）です。</p>\n<p>記録最低気温が−10°Cのサイトでは、係数は約1.09です — ほとんどの氷点下気候では9～12%と考えてください。銘板ではなく、その補正された数値を最大PV入力電圧と比較してください。有用な机上チェック：寒冷気候では、STCストリングVocを入力上限のおよそ90%以下に保てば、冬に驚くことはありません。</p>\n<p>これはまた、「倉庫では動作した」ということが何の意味も持たない理由でもあります。倉庫は決して−10°Cで、トラッカーに負荷がかかっていない状態ではありませんでした。</p>\n<h2>ウィンドウの内側：ストリング、下限、暑い屋根</h2>\n<p>MPPT動作範囲は、トラッカーが動作する電圧帯です — たとえば、当社の <a href=\"/products/off-grid-solar-inverters/\">MKS II 5K</a> は、48Vバンクで120～430 Vdcを記載しています。直列接続されたモジュールは、この帯域を通してストリング電圧を押し上げます。並列接続されたモジュールは電流を追加するだけです。失敗の方向は2つあり、寒い朝の罠は暑い屋根で鏡像を持ちます：</p>\n<ul>\n<li><strong>上限を超える。</strong> 直列接続するモジュールが多すぎる：Voc（寒冷時）が最大入力電圧を超えます。上記のようにハードウェアが損傷します。</li>\n<li><strong>下限を下回る。</strong> 直列接続するモジュールが少なすぎる：ストリングVmpがMPPT範囲の下限を下回ります。暑い屋根では、Vmpも1度あたり約0.3～0.4%低下します — 25°Cで120Vの下限をちょうどクリアする3モジュールのストリングは、セルが60°Cに達するとそれを下回り、午後半ばにトラッキングが停止します。</li>\n</ul>\n<p>したがって、ウィンドウは両側から切り取ります。実用的なルール：暑い気候の低減<em>後</em>にVmpが下限を十分に上回り、寒冷気候の補正<em>後</em>にVocが上限を下回るようにストリングを設計します。データシートには、MPPT下限より少し上の起動電圧が記載されている場合もあります — それはわずかにマージンの少ない同じチェックとして扱ってください。</p>\n<h2>実際の48Vプラットフォームでの計算例</h2>\n<p>一般的な540Wモジュールを例にとります：Voc 49.4V、STCでVmp 41.7V、Voc温度係数 −0.27%/°C。サイトは冬に−10°C、夏に60°Cのセル温度に達します。インバーターは48Vユニットで、MPPT範囲は120～430 Vdcです — 値は <a href=\"/products/off-grid-solar-inverters/\">MKS II 5K</a> と正確に一致します。</p>\n<table>\n<thead>\n<tr>\n<th>直列接続モジュール数</th>\n<th>Voc（STC）</th>\n<th>−10°CでのVoc</th>\n<th>セル60°CでのVmp</th>\n<th>判定</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3</td>\n<td>148V</td>\n<td>162V ✅</td>\n<td>110V ❌ 下限未満</td>\n<td>暑い午後にトラッキングが停止</td>\n</tr>\n<tr>\n<td>4</td>\n<td>198V</td>\n<td>216V ✅</td>\n<td>147V ✅</td>\n<td>両方のチェックに合格</td>\n</tr>\n<tr>\n<td>7</td>\n<td>346V</td>\n<td>379V ✅</td>\n<td>256V ✅</td>\n<td>余裕がある — 正解</td>\n</tr>\n<tr>\n<td>8</td>\n<td>395V</td>\n<td>433V ❌ 上限超過</td>\n<td>293V ✅</td>\n<td>冬に入力段が危険にさらされる</td>\n</tr>\n</tbody>\n</table>\n<p>この表はすべてを物語っています：3モジュールは電圧上限を通過しますが下限で失敗します。8モジュールは夏には美しくトラッキングしますが、最初の霜で入力を破壊します。ストリングあたり7モジュール — 約3.8kWのアレイ — は、両側にマージンを持ってすべてのチェックに合格します。次に、アレイの合計電力が、そのモデルのデータシートの最大PV入力電力と照合されます。5kWクラスのユニットの場合、2つ目のMPPT入力や控えめな将来の拡張のための余裕が残ります。</p>\n<h2>ウィンドウが意図的に狭い場合</h2>\n<p>すべてのモデルが長いストリングを望むわけではありません。一部のプラットフォームは特定のアレイ形状を中心に構築されており、そのウィンドウはそれに対応して狭くなっています：たとえば、当社のSC-PS 3Kは、30～32 VdcのMPPT範囲を指定しています — 事実上、トラッカーあたり1モジュールで、2モジュール直列ストリングの余地はありません。狭いウィンドウは欠陥ではありません。それは、そのモデルが特定の構成のために設計されたという信号です。どのアレイでも適合すると仮定する前に、それを読んでください。</p>\n<p>カタログ全体の広がりは、B2Bバイヤーにとって重要です。<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーターシリーズ</a> — そのMPPTウィンドウは、単一モジュールの30～32 Vdcから48Vプラットフォームの90～500 Vdcにまで及びます — と、12～72Vのバッテリー側入力オプションを備えた<a href=\"/products/off-grid-inverters/\">プレーンなオフグリッドインバーター</a>の間で、ほとんどのプロジェクト構成はカスタム作業なしでマッチングできます。スキルは、まずウィンドウを読み、次にアレイを設計することであり、その逆ではありません。</p>\n<h2>並列ストリング：電流はもう一つの制限</h2>\n<p>直列電圧はストリング設計の半分に過ぎません。アレイが1つのストリングが供給するよりも多くの電流を必要とする場合、ストリングは単一のMPPT入力に並列接続されます — そして、入力の短絡電流定格が拘束条件となります。2つのチェック：</p>\n<ol>\n<li>並列接続されたすべてのストリングのIscを合計し、入力の最大電流定格を下回ることを確認します。電流も高くなる寒冷で晴天の日のためのマージンを考慮します。</li>\n<li>並列接続されたストリングが電気的に対称であることを確認します — 同じモジュールモデル、同じ数、同じ向き。並列接続された混合ストリングは、トラッカーで電力を浪費し、部分的な日陰の動作を混乱させる可能性があります。</li>\n</ol>\n<p>多くの高出力モデルは、2つ以上の独立したMPPT入力を備えています。その場合は、不一致のストリングを1つのトラッカーに並列接続するのではなく、入力ごとに1つの屋根面または向きを割り当ててください。</p>\n<h2>発注前の5分チェック</h2>\n<p>インバーターとアレイのペアの発注を確定する前に、これを実行してください：</p>\n<ul>\n<li>サイトの記録最低温度でのストリングVoc &#x3C; 最大PV入力電圧</li>\n<li>暑い気候の低減後のストリングVmp > MPPT範囲下限</li>\n<li>ストリングVmp（あらゆる条件） &#x3C; MPPT範囲上限</li>\n<li>アレイの合計ワット数 ≤ データシートの最大PV入力電力</li>\n<li>並列ストリングのIsc ≤ 入力電流定格</li>\n<li>MPPT入力ごとに1つの向き。対称ストリングのみ。</li>\n</ul>\n<p>2つのデータシートを使った5分間で、最も高価なクラスのPV側故障を防ぐことができます — 試運転から数ヶ月後、冬に、誰も二度訪れたくないサイトで現れる種類の故障です。</p>\n<h2>バイヤーがウィンドウを正しく設定するための支援方法</h2>\n<p>PV入力に関する質問は、当社のセールスエンジニアリングデスクで毎日寄せられます。なぜなら、ほとんどのB2B顧客は、当社が事前に把握していない市場やモジュール構成のためにアレイを設計するからです。2010年以来、当社は文書化された広いMPPTウィンドウを中心に<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーターライン</a>を構築してきました — 単一モジュールプラットフォームから450 Vdcおよび500 Vdc上限モデルまで — そしてすべての製品ページに正確な範囲が記載されているため、ストリング計算は問い合わせの前に行うことができます。</p>\n<p>アレイ設計が2つのモデルの間にある場合は、<a href=\"/contact/\">お問い合わせフォーム</a>からモジュールのデータシートとサイトの温度範囲を送信してください。当社のエンジニアが、発注前にどのウィンドウが適合するかを書面で確認します。</p>\n<section aria-label=\"MPPTウィンドウとPV入力サイジング — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">MPPTウィンドウとPV入力サイジング — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">MPPT範囲の制限はVocとVmpのどちらに適用されますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">Vmpに適用されます — 電力生産中にストリングが動作する電圧です。Vocは最大PV入力電圧に対して別途チェックされ、これは厳しく容赦のない上限です。同じストリング上の2つの数値は約15～20%異なり、それぞれに独自の制限があります。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">アレイが最大PV入力電圧を超えるとどうなりますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">入力段が永久に損傷する可能性があります。通常、トラッカーが電流を引き込み始める前の寒い朝に発生します。ヒューズが切れたりブレーカーが落ちたりすることなく故障し、過電圧損傷は保証対象外です。これは、PV側のサイジングミスの中で最も高価なものです。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">430 Vdc入力に直列接続できるパネル数はいくつですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">最大入力電圧を、モジュールの寒冷補正済みVoc（銘板値ではなく）で割ります。−10°Cの気候における49.4Vモジュールの場合、7モジュール（寒冷時約379V）はマージンを持って合格しますが、8モジュール（寒冷時約433V）は上限を超えます — したがって答えは7です。25°Cでは紙の上では8が適合しますが。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">長さの異なる2つのストリングを1つのMPPT入力に並列接続できますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。並列接続するストリングは同一でなければなりません — 同じモジュール、同じ直列数、同じ向き。並列接続された不一致のストリングでは、電流が弱いストリングを逆流し、電力を浪費し、モジュールに負担をかけます。代わりに、異なる向きを別々のMPPT入力に割り当ててください。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"MPPT範囲の制限はVocとVmpのどちらに適用されますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Vmpに適用されます — 電力生産中にストリングが動作する電圧です。Vocは最大PV入力電圧に対して別途チェックされ、これは厳しく容赦のない上限です。同じストリング上の2つの数値は約15～20%異なり、それぞれに独自の制限があります。\"}},{\"@type\":\"Question\",\"name\":\"アレイが最大PV入力電圧を超えるとどうなりますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"入力段が永久に損傷する可能性があります。通常、トラッカーが電流を引き込み始める前の寒い朝に発生します。ヒューズが切れたりブレーカーが落ちたりすることなく故障し、過電圧損傷は保証対象外です。これは、PV側のサイジングミスの中で最も高価なものです。\"}},{\"@type\":\"Question\",\"name\":\"430 Vdc入力に直列接続できるパネル数はいくつですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"最大入力電圧を、モジュールの寒冷補正済みVoc（銘板値ではなく）で割ります。−10°Cの気候における49.4Vモジュールの場合、7モジュール（寒冷時約379V）はマージンを持って合格しますが、8モジュール（寒冷時約433V）は上限を超えます — したがって答えは7です。25°Cでは紙の上では8が適合しますが。\"}},{\"@type\":\"Question\",\"name\":\"長さの異なる2つのストリングを1つのMPPT入力に並列接続できますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。並列接続するストリングは同一でなければなりません — 同じモジュール、同じ直列数、同じ向き。並列接続された不一致のストリングでは、電流が弱いストリングを逆流し、電力を浪費し、モジュールに負担をかけます。代わりに、異なる向きを別々のMPPT入力に割り当ててください。\"}}]}</script>",
  },
  "inverter-surge-power-motor-starting": {
    title: "サージ電力とモーター始動：ポンプ、電動工具、コンプレッサーに適したインバーターの選定方法",
    description: "モーターは始動時に定格運転時の数倍の電力を消費します。サージ定格の読み方、実際の始動需要の見積もり、ポンプ起動時に停止しないオフグリッドインバーターの選定方法を解説します。",
    tags: [
      "インバーター選定",
      "オフグリッド",
      "モーター負荷",
    ],
    bodyHtml: "<p>インバーターは、総運転負荷を十分に上回る定格であっても、ポンプ、冷蔵庫、エアコンプレッサーが始動しようとした瞬間に停止することがあります。\nその理由はサージ電力です。これは電動モーターが最初の一瞬に引き込む、短時間ながら膨大な電流です。\nサージを考慮した容量選定は、正しく見える仕様書と現場で機能するシステムとの間にある、最も一般的なギャップです。</p>\n<h2>モーターが「十分な」インバーターを停止させる理由</h2>\n<p>誘導モーターは単純にスイッチが入るわけではありません。運転速度に達する前は、ほぼ短絡に近い状態で動作します。ローターが静止しているため、巻線は最大すべりを受け、<strong>拘束電流</strong>を引き込みます。これは通常、運転電流の3～7倍で、0.数秒（小型ファン）から2～3秒（負荷のかかったポンプやコンプレッサー）続きます。</p>\n<p>さらに2つの要因が重なります：</p>\n<ul>\n<li><strong>力率。</strong> 始動時、モーターの力率は0.3～0.5付近まで低下するため、インバーターが供給しなければならない皮相電力（VA）は、運転ワット数から想像されるよりもはるかに大きくなります。</li>\n<li><strong>電圧降下。</strong> サージが流れている間、インバーターの出力電圧は低下します。降下が十分に深い場合、同じ回路の他の電子機器がリセットされ、インバーター自体がこの事象を短絡と解釈してラッチオフすることがあります。</li>\n</ul>\n<p>抵抗負荷 — ケトル、オーブン、白熱照明 — は決してこのような動作をしません。だからこそ、同じ運転ワット数を持つ2つのシステムが現場でまったく異なる挙動を示すことがあります。</p>\n<h2>すべてのインバーター仕様書にある2つの数値</h2>\n<p>インバーター容量は常に2通りに記載され、両方の行が重要です：</p>\n<table>\n<thead>\n<tr>\n<th>仕様</th>\n<th>意味</th>\n<th>一般的な数値</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>連続（定格）電力</td>\n<td><code>25°C</code>で無期限に供給できるACワット数</td>\n<td>主要数値、例：3000W</td>\n</tr>\n<tr>\n<td>ピーク / サージ電力</td>\n<td>短時間の過負荷、通常5～30秒</td>\n<td>一般に定格の2倍。低周波設計では3倍以上に達することも</td>\n</tr>\n</tbody>\n</table>\n<p>これらの数値を誠実に読むための3つのルール：</p>\n<ol>\n<li><strong>サージの<em>持続時間</em>を確認し、倍率だけを見ないこと。</strong> 「5秒間2倍」という定格は軽負荷のポンプには対応できますが、長い立ち上がり時間を持つ深井戸ポンプには対応できません。持続時間が示されていない定格は、ほとんど無意味です。</li>\n<li><strong>サージは連続使用のための追加余裕ではありません。</strong> これはモーター始動をカバーするためだけに存在します。サージ帯域内で負荷を連続運転する計画は決して立てないでください。</li>\n<li><strong>サージ能力はDC側にも依存します。</strong> インバーターは、バッテリーバンクとケーブルがサージを供給できる場合にのみ、サージを供給できます。細いケーブルで小型の12Vバッテリーに接続された3000Wインバーターは、ユニット自体が対応できたとしてもサージで停止します。3000Wでは、12Vバンクはおよそ<code>250A</code>（<code>3000 ÷ 12 × 1.1</code>の効率補正）を供給する必要がありますが、同じ負荷を48Vで使用すると約<code>69A</code>を消費します。</li>\n</ol>\n<h2>サージを発生させる負荷</h2>\n<p>家庭や工房での障害のほとんどは、少数の誘導負荷に起因します。一般的な単相機器の代表的な数値：</p>\n<table>\n<thead>\n<tr>\n<th>負荷</th>\n<th>運転ワット数</th>\n<th>一般的な始動消費</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>LED照明、ノートPC、テレビ</td>\n<td>10–150W</td>\n<td>1倍（サージなし）</td>\n</tr>\n<tr>\n<td>冷蔵庫 / 冷凍庫</td>\n<td>100–300W</td>\n<td>約1秒間3～6倍</td>\n</tr>\n<tr>\n<td>シーリングファン</td>\n<td>60–120W</td>\n<td>短時間2～3倍</td>\n</tr>\n<tr>\n<td>0.5 HP 陸上ポンプ</td>\n<td>~400–750W</td>\n<td>1～2秒間3～5倍</td>\n</tr>\n<tr>\n<td>1 HP 水中ポンプ</td>\n<td>~1000–1500W</td>\n<td>1～3秒間3～6倍</td>\n</tr>\n<tr>\n<td>エアコンプレッサー（2 HP 工房用クラス）</td>\n<td>~1500W</td>\n<td>2～3秒間4～6倍</td>\n</tr>\n<tr>\n<td>セパレート形エアコン（1 ton）</td>\n<td>~900–1200W</td>\n<td>コンプレッサー始動時4～6倍</td>\n</tr>\n<tr>\n<td>電動ノコギリ / アングルグラインダー</td>\n<td>800–1500W</td>\n<td>負荷がかかった時2～3倍</td>\n</tr>\n</tbody>\n</table>\n<p>これらは工学上の経験則であり、データシートの値ではありません。モーターの銘板またはポンプのデータシートに**拘束電流（LRA）**の値が記載されている場合は、それを使用してください：<code>サージワット ≈ LRA × 電圧</code>。馬力のみが記載されている場合、230Vの1 HP単相モーターは運転時に約6～8Aを消費し、始動時には一時的に40A以上を引き込むことがあります。</p>\n<h2>容量選定の計算例</h2>\n<p>シナリオ：ワクチン冷蔵庫、照明、ノートPC充電ステーション、0.75 kW水中ポンプを備えた地方の診療所。</p>\n<p><strong>ステップ1 — 運転負荷。</strong> 冷蔵庫200W + 照明150W + ノートPC 200W + ポンプ750W = 同時に重なる可能性のある負荷<code>1300W</code>。25%の余裕を追加 → 連続最小<code>1625W</code>。</p>\n<p><strong>ステップ2 — 最悪ケースのサージ。</strong> 支配的な事象は、他のすべてが運転している<em>最中</em>にポンプが始動することです。ポンプのサージを運転時の4倍とすると：<code>750 × 4 = 3000W</code>、さらに他の定常負荷500W → 瞬間需要<code>3500W</code>。</p>\n<p><strong>ステップ3 — 仕様書との照合。</strong> ステップ1（≈ 2000W）を<em>連続</em>定格がカバーし、ステップ2（最大2秒間で3500W）を<em>サージ</em>定格がカバーするインバーターが必要です。2倍（5000W）のサージ仕様を持つ2500Wユニットは両方の数値を満たします。文書化されていない「ピーク」値のみの2000Wユニットはギャンブルです。</p>\n<p><strong>ステップ4 — DC側の確認。</strong> 24Vでは、サージ電流はおよそ<code>3500 ÷ 24 ≈ 146A</code>です。バッテリーバンク、メインヒューズ、バッテリーケーブルはすべて、その瞬間電流に耐えられる定格でなければなりません。これが、この規模以上のシステムで48Vが実用的な選択となる理由の1つです。</p>\n<p>負荷リストがこの例のような場合、当社の<a href=\"/products/off-grid-solar-inverters/\">オフグリッド太陽光インバーター</a>はMPPT充電内蔵で1.5～11 kWの範囲をカバーし、<a href=\"/products/off-grid-inverters/\">スタンドアロン形オフグリッドインバーター</a>はバッテリーベースのシステム向けに12V～72V DC入力オプションを備え、0.9～5 kWを網羅します。</p>\n<h2>サージが予算を超える場合の設計上の手段</h2>\n<p>正直なサージ計算が予算を超える場合でも、より大きなインバーターを買うだけという衝動に抵抗してください。より安価な手段がいくつかあります：</p>\n<ul>\n<li><strong>始動をずらす。</strong> ほとんどの停止は2つのモーターが同時に始動することが原因です。タイマーまたは簡単な運用ルール（「ポンプとエアコンを同じ分に起動しない」）で、サージ要件を半減できます。</li>\n<li><strong>最大のモーターにソフトスターターを取り付ける。</strong> コンプレッサーまたはポンプにソフトスタートモジュールを付けると、突入電流を運転電流のおよそ2倍に制限できます。深井戸ポンプでは、これが3kWと6kWのインバーターの違いになることがよくあります。</li>\n<li><strong>システム電圧を上げる。</strong> 同じワット数では、バッテリー電圧を2倍にするとDC電流が半減し、ケーブル発熱が減り、インバーターがサージ中も出力電圧をより安定して維持できます。トレードオフの全体像については、<a href=\"/blog/12v-24v-48v-inverter-system/\">12V、24V、48Vの選び方</a>のガイドをご覧ください。</li>\n<li><strong>ポンプ負荷の多い現場では低周波トポロジーを検討する。</strong> 低周波設計のトランスは、コンパクトな高周波ユニットよりもサージをスムーズに吸収します。詳細な比較は<a href=\"/blog/low-frequency-vs-high-frequency-inverter/\">低周波数と高周波数の比較ガイド</a>にあります。</li>\n<li><strong>PVアレイを過大にしても役に立ちません。</strong> アレイのワット数はバッテリーを充電するものであり、1秒未満のサージ中にAC出力に現れるものではありません。アレイの容量選定は別の作業であり、<a href=\"/blog/how-many-solar-panels-for-off-grid/\">パネル枚数の計算ワークシート</a>で扱っています。</li>\n</ul>\n<h2>試運転チェック：最悪ケースをテストする</h2>\n<p>引き渡し後にサージ限界を発見することのないようにしてください。現場受け入れ前に、システムが経験する最も過酷な単一の事象を実行してください。他の主要な負荷がすべてオンの状態で、最大のモーターを始動します。確認する点：</p>\n<ul>\n<li>インバーターは停止せずに始動を乗り切りますか？</li>\n<li>照明が目立って暗くなりますか？（短時間の浅い電圧低下は正常です。電子機器をリセットするようなちらつきは、DCケーブルまたはバッテリー容量が限界ぎりぎりであることを意味します。）</li>\n<li>始動中、インバーター端子のバッテリー電圧は低DCカットオフを上回ったままですか？</li>\n</ul>\n<p>15分間の意図的な最悪ケーステストで、現場からのコールバックのほとんどを防げます。</p>\n<h2>当社のサポート</h2>\n<p>システムがどのようなモーターを運転するか — ポンプの種類と出力、コンプレッサーのサイズ、始動方法 — を当社のセールスエンジニアにお知らせください。負荷に合ったサージプロファイルのインバーターを推奨します。コンパクトな<a href=\"/products/off-grid-inverters/\">オフグリッドインバーターシリーズ</a>から<a href=\"/products/off-grid-solar-inverters/\">高出力オフグリッド太陽光インバーター</a>まで、<a href=\"/products/\">全製品カタログ</a>でご確認いただけます。</p>\n<section aria-label=\"サージ電力 — FAQ\"><h2 class=\"mb-6 text-2xl font-semibold text-slate-900\">サージ電力 — FAQ</h2><div class=\"divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white\"><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">モーターは始動時に定格ワット数の何倍の電力を消費しますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">通常、モーターのサイズ、種類、機械的負荷に応じて、0.数秒から2～3秒の間、3～7倍になります。ポンプとコンプレッサーは高い側、ファンは低い側です。入手可能な場合は、銘板の拘束電流（LRA）を使用してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">インバーターのサージ定格は連続定格の2倍ですか、3倍ですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">設計によります。多くのコンパクトな高周波ユニットは数秒間、定格出力の約2倍を提供します。低周波トランスベースの設計は、しばしば3倍以上を持続します。倍率と同じくらい持続時間が重要なので、過負荷がどのくらいの時間サポートされるかを確認し、モーターの始動時間と照合してください。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">負荷が定格を大幅に下回っているのに、インバーターが停止したのはなぜですか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">ほとんどの場合、モーター始動が原因です。どの誘導負荷が同じ回路を共有しているかを確認し、それらの始動電力を推定し、始動をずらす、最大のモーターにソフトスターターを追加する、またはより高いサージ定格のインバーターに移行するなどの対策を行ってください。また、バッテリーとケーブルがサージ電流を供給できることを確認してください。DC側が弱い場合も同じ保護が作動します。</p></details><details class=\"group px-5 py-4\"><summary class=\"flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-medium text-slate-900 marker:hidden [&::-webkit-details-marker]:hidden\">より大きな太陽光アレイはサージによる停止を解決しますか？<svg class=\"h-5 w-5 shrink-0 text-slate-400 transition-transform group-open:rotate-180\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\"><path fill-rule=\"evenodd\" d=\"M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z\" clip-rule=\"evenodd\" /></svg></summary><p class=\"mt-3 text-sm leading-relaxed text-slate-600\">いいえ。アレイはAC出力ではなくバッテリーに電力を供給し、モーターサージはMPPTトラッキングが寄与するにはあまりにも短時間です。サージ容量はインバーターの設計と、バッテリーバンクが高電流を供給する能力からもたらされます。</p></details></div></section><script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"モーターは始動時に定格ワット数の何倍の電力を消費しますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"通常、モーターのサイズ、種類、機械的負荷に応じて、0.数秒から2～3秒の間、3～7倍になります。ポンプとコンプレッサーは高い側、ファンは低い側です。入手可能な場合は、銘板の拘束電流（LRA）を使用してください。\"}},{\"@type\":\"Question\",\"name\":\"インバーターのサージ定格は連続定格の2倍ですか、3倍ですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"設計によります。多くのコンパクトな高周波ユニットは数秒間、定格出力の約2倍を提供します。低周波トランスベースの設計は、しばしば3倍以上を持続します。倍率と同じくらい持続時間が重要なので、過負荷がどのくらいの時間サポートされるかを確認し、モーターの始動時間と照合してください。\"}},{\"@type\":\"Question\",\"name\":\"負荷が定格を大幅に下回っているのに、インバーターが停止したのはなぜですか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"ほとんどの場合、モーター始動が原因です。どの誘導負荷が同じ回路を共有しているかを確認し、それらの始動電力を推定し、始動をずらす、最大のモーターにソフトスターターを追加する、またはより高いサージ定格のインバーターに移行するなどの対策を行ってください。また、バッテリーとケーブルがサージ電流を供給できることを確認してください。DC側が弱い場合も同じ保護が作動します。\"}},{\"@type\":\"Question\",\"name\":\"より大きな太陽光アレイはサージによる停止を解決しますか？\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"いいえ。アレイはAC出力ではなくバッテリーに電力を供給し、モーターサージはMPPTトラッキングが寄与するにはあまりにも短時間です。サージ容量はインバーターの設計と、バッテリーバンクが高電流を供給する能力からもたらされます。\"}}]}</script>",
  },
};
